from typing import List

def longest_decreasing_subsequence(arr: List[int]) -> int:
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # Each element is a subsequence of length 1 by itself

    for i in range(1, n):
        for j in range(i):
            if arr[j] > arr[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def limited_memory_merge_sort(arr, reverse=False):
    """
    Simplified Merge Sort implementation with limited memory usage.

    :param arr: Unordered input list
    :param reverse: Descent ordering flag
    :return: Sorted list in the specified order
    """
    if not arr or len(arr) <= 1:
        return arr

    def merge(left, right, buffer):
        l = r = 0
        while l < len(left) and r < len(right):
            if (left[l] < right[r] and not reverse) or (left[l] > right[r] and reverse):
                buffer.append(left[l])
                l += 1
            else:
                buffer.append(right[r])
                r += 1
        while l < len(left):
            buffer.append(left[l])
            l += 1
        while r < len(right):
            buffer.append(right[r])
            r += 1

    def merge_sort_recursive(sub_arr, buffer):
        if len(sub_arr) <= 1:
            return sub_arr
        mid = len(sub_arr) // 2
        left = merge_sort_recursive(sub_arr[:mid], buffer)
        right = merge_sort_recursive(sub_arr[mid:], buffer)
        buffer.clear()
        merge(left, right, buffer)
        return list(buffer)

    buffer = []
    return merge_sort_recursive(arr, buffer)

