import heapq

def k_smallest_elements(data: list, k: int) -> list:
    """
    Returns the k smallest elements from the list 'data' in ascending order.
    """
    if k == 0 or not data:
        return []

    # Use a heap to efficiently find the k smallest elements
    k_smallest = heapq.nsmallest(k, data)
    return sorted(k_smallest)

