def normalize_path(path: str) -> str:
    """
    Normalize the given UNIX-like file system path by removing redundant components.

    :param path: An absolute UNIX path in string format.
    :return: The canonical path as a string.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    normalized = '/' + '/'.join(stack)
    return normalized

