from typing import List

def is_preorder_traversal_bst(arr: List[int]) -> bool:
    """
    Check if the given list can represent the preorder traversal of a BST.
    """
    if not arr:
        return True

    stack = []
    root = float('-inf')

    for value in arr:
        if value < root:
            return False

        while stack and stack[-1] < value:
            root = stack.pop()

        stack.append(value)

    return True

