def min_cost_to_end(costs: list[int]) -> int:
    n = len(costs)

    if n == 1:
        return costs[0]

    # Initialize dp variables for the previous two minimum costs
    prev1, prev2 = costs[0], costs[1]

    for i in range(2, n):
        current = costs[i] + min(prev1, prev2)
        prev1, prev2 = prev2, current

    return min(prev1, prev2)

