def group_and_sort_employees(employees, departments):
    from collections import defaultdict

    department_dict = defaultdict(list)

    for employee, department in zip(employees, departments):
        department_dict[department].append(employee)

    # Sort the employees within each department
    for dept in department_dict:
        department_dict[dept].sort()

    # Convert the defaultdict back to a regular dict for the final output
    return dict(sorted(department_dict.items()))

