def longest_word(words: list) -> str:
    """
    Returns the longest word in the list. If multiple words have the
    longest length, the first one encountered is returned.
    """
    if not words:
        raise ValueError("Invalid input")

    # Check each word for alphabetic characters only and non-empty strings
    for word in words:
        if not word.isalpha():
            raise ValueError("Invalid input")

    # Initialize the longest word tracking
    longest = words[0]

    # Find the longest word
    for word in words:
        if len(word) > len(longest):
            longest = word
    return longest

