from typing import List, Optional

def calculate_moving_average(numbers: List[int], window_size: int) -> List[Optional[float]]:
    if window_size <= 0 or window_size > len(numbers):
        raise ValueError("Invalid window size")

    moving_averages = []
    for i in range(len(numbers)):
        # For the first (window_size - 1) elements, append None
        if i < window_size - 1:
            moving_averages.append(None)
        else:
            # Calculate the moving average for the window
            window = numbers[i-window_size+1:i+1]
            average = sum(window) / window_size
            moving_averages.append(average)
    return moving_averages

