from typing import List

def longestSubarrayWithSumK(arr: List[int], k: int) -> int:
    sum_map = {}
    current_sum = 0
    max_length = 0

    for i in range(len(arr)):
        # Add the current element to the current_sum
        current_sum += arr[i]

        # If current_sum is equal to k, we found a subarray starting from index 0
        if current_sum == k:
            max_length = i + 1

        # If (current_sum - k) exists in sum_map, update max_length if we get a larger subarray length
        if (current_sum - k) in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        # Add current_sum to sum_map if it is not already present
        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

def longest_substring_with_k_distinct(s: str, k: int) -> int:
    from collections import defaultdict

    if k == 0 or not s:
        return 0

    char_frequency = defaultdict(int)
    left = 0
    max_length = 0

    for right in range(len(s)):
        char_frequency[s[right]] += 1

        while len(char_frequency) > k:
            char_frequency[s[left]] -= 1
            if char_frequency[s[left]] == 0:
                del char_frequency[s[left]]
            left += 1

        if len(char_frequency) == k:
            max_length = max(max_length, right - left + 1)

    return max_length

