def are_permutations(str1: str, str2: str) -> bool:
    """
    Determines whether two strings are permutations of each other.
    """
    # First, quick check: if lengths differ, they cannot be permutations.
    if len(str1) != len(str2):
        return False

    # Create a dictionary to count character occurrences in str1.
    count = {}

    # Count each character in str1.
    for char in str1:
        count[char] = count.get(char, 0) + 1

    # Subtract counts using characters in str2.
    for char in str2:
        if char not in count:
            return False  # If a char in str2 doesn't exist in str1, they are not permutations
        count[char] -= 1
        if count[char] < 0:
            return False  # More occurrences of a char in str2 than in str1

    return True

