def keyword_search(titles: list, keywords: list) -> list:
    """
    Returns a list of book titles that contain any of the given keywords.
    """
    if not titles or not keywords:
        return []

    result = []
    lower_keywords = {k.lower() for k in keywords}

    for title in titles:
        lower_title = title.lower()
        if any(keyword in lower_title for keyword in lower_keywords):
            result.append(title)

    return result

