def generate_binary_tree(depth: int) -> dict:
    """
    Generate a binary tree of specified depth as a nested dictionary structure.
    """
    def add_children(node: dict, current_depth: int, max_depth: int) -> None:
        if current_depth < max_depth:
            node['left'] = {}
            node['right'] = {}
            add_children(node['left'], current_depth + 1, max_depth)
            add_children(node['right'], current_depth + 1, max_depth)

    root = {}
    add_children(root, 0, depth)
    return root

def calculate_depth(tree: dict) -> int:
    """
    Calculate the depth of a binary tree represented as nested dictionaries.
    """
    if not tree:
        return 0
    left_depth = calculate_depth(tree.get('left', {}))
    right_depth = calculate_depth(tree.get('right', {}))
    return 1 + max(left_depth, right_depth)

