def primary_diagonal_sum(matrix):
    """
    Returns the sum of the primary diagonal elements of the matrix.
    """
    return sum(matrix[i][i] for i in range(len(matrix)))

def secondary_diagonal_sum(matrix):
    """
    Returns the sum of the secondary diagonal elements of the matrix.
    """
    n = len(matrix)
    return sum(matrix[i][n-i-1] for i in range(n))

def diagonal_sum(matrix):
    """
    Returns the combined sum of the primary and secondary diagonals.
    """
    return primary_diagonal_sum(matrix) + secondary_diagonal_sum(matrix)

from typing import List, Tuple

def final_position(commands: List[str]) -> Tuple[int, int]:
    """
    Calculates the final position of the robot after executing a series of movement commands.

    Parameters:
    commands (list of str): A list of movement commands ('UP', 'DOWN', 'LEFT', 'RIGHT').

    Returns:
    tuple: Final coordinates (x, y) on the 2D plane.
    """
    x, y = 0, 0  # initial position

    # process each command
    for command in commands:
        if command == "UP":
            y += 1
        elif command == "DOWN":
            y -= 1
        elif command == "LEFT":
            x -= 1
        elif command == "RIGHT":
            x += 1

    return (x, y)

