def max_profit(prices):
    """
    Given an array of prices where each price represents an item in the stock market,
    calculates the maximum profit you can achieve by buying and selling exactly once.
    Returns 0 if no profit is possible or if the array is empty/contains one element.
    """
    if not prices or len(prices) < 2:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

from typing import List

def count_removals_to_strictly_increasing(heights: List[int]) -> int:
    """
    Returns the minimum number of removals needed to make the heights strictly increasing.
    """
    if not heights:
        return 0

    removals = 0
    n = len(heights)

    for i in range(1, n):
        if heights[i] == heights[i-1]:
            removals += 1

    return removals

