def subset_sum_exists(arr, target):
    """
    Determines if there is a subset of `arr` that sums to `target`.

    :param arr: List of integers
    :param target: Integer target sum
    :return: True if such a subset exists, otherwise False
    """
    n = len(arr)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if j < arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    return dp[n][target]

