def first_non_repeated_character(s):
    """
    Returns the first non-repeated character in the string s.
    If there is no such character, returns an empty string.
    """
    # Dictionary to store count of each character
    char_count = {}

    # Iterate through the string and count characters
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate through the string again to find the first non-repeated character
    for char in s:
        if char_count[char] == 1:
            return char

    # If no non-repeated character is found, return an empty string
    return ""

