def word_frequency(sentence: str) -> dict:
    """
    Returns a dictionary where each key is a unique word
    (case-insensitive) in the input string, and the corresponding value
    is the count of occurrences of that word.
    """
    words = sentence.lower().split()
    freq_dict = {}

    for word in words:
        if word in freq_dict:
            freq_dict[word] += 1
        else:
            freq_dict[word] = 1

    return freq_dict

