def contains_nearby_duplicate(nums, k):
    """
    Returns true if there are duplicate integers in the array such that
    the difference between the indices of the duplicate integers is at most k.
    """
    num_indices = {}

    for i, num in enumerate(nums):
        if num in num_indices and i - num_indices[num] <= k:
            return True
        num_indices[num] = i

    return False

