def first_missing_positive(nums):
    """
    Returns the first missing positive integer from the list nums.
    The function modifies the input list in place and uses constant extra space.
    """
    n = len(nums)

    for i in range(n):
        # Loop to place numbers at their correct indices if possible
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap the numbers to their correct positions
            correct_index = nums[i] - 1
            nums[i], nums[correct_index] = nums[correct_index], nums[i]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

