def most_frequent_char(s):
    """
    Returns the most frequently occurring character in the string. If there are multiple characters
    with the same maximum frequency, returns the character that appears first in the string.
    If the input string is empty, returns an empty string.
    """
    if not s:
        return ""

    char_count = {}
    for index, char in enumerate(s):
        if char in char_count:
            char_count[char][0] += 1
        else:
            char_count[char] = [1, index]

    max_occurrence = -1
    result_char = ''

    for char, (count, index) in char_count.items():
        if count > max_occurrence or (count == max_occurrence and index < char_count[result_char][1]):
            max_occurrence = count
            result_char = char

    return result_char

