def evaluate_expression(expression):
    """
    Evaluates a string arithmetic expression containing
    non-negative integers and '+', '-', '*', and '/' operators with normal precedence rules.
    """
    if not expression:
        return 0

    num, stack, sign = 0, [], '+'
    expression = expression.replace(' ', '')

    for i, ch in enumerate(expression):
        if ch.isdigit():
            num = num * 10 + int(ch)
        if ch in '+-*/' or i == len(expression) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack[-1] = stack[-1] * num
            elif sign == '/':
                stack[-1] = int(stack[-1] / num)  # integer division
            num, sign = 0, ch

    return sum(stack)

def char_frequency(s):
    """
    Process a string and calculates the frequency of each character in the string.
    Disregards case sensitivity and ignores non-alphabetic characters.

    Args:
    s (str): Input string

    Returns:
    list: List of tuples containing characters and their frequencies in alphabetical order.
    """
    # Filter out non-alphabetic characters and convert to lowercase
    filtered_string = ''.join([char.lower() for char in s if char.isalpha()])

    # Calculate the frequency of each character
    frequency_dict = {}
    for char in filtered_string:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1

    # Return the sorted list of tuples
    return sorted(frequency_dict.items())

def can_form_palindrome_by_deleting_one_char(s):
    def is_palindrome(subs):
        return subs == subs[::-1]

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            # Try removing either the left or the right character and check
            return is_palindrome(s[left:right]) or is_palindrome(s[left + 1:right + 1])
        left += 1
        right -= 1

    return True

