def calculate_plant_height(plant_type, initial_height, days):
    """
    Calculate the height of a plant after a given number of days based on its growth type.

    Parameters:
        plant_type (str): Type of plant ('A', 'B', or 'C')
        initial_height (float): Initial height of the plant in centimeters
        days (int): Number of days for which the growth is to be calculated

    Returns:
        float: Expected height of the plant rounded to the nearest tenth of a centimeter
    """

    if plant_type not in ('A', 'B', 'C'):
        raise ValueError("Invalid plant type. Type must be 'A', 'B', or 'C'.")

    if initial_height < 0:
        raise ValueError("Initial height cannot be negative.")

    if not isinstance(days, int) or days < 0:
        raise ValueError("Number of days must be a non-negative integer.")

    current_height = initial_height

    if plant_type == 'A':
        for _ in range(days):
            current_height += current_height * 0.05
    elif plant_type == 'B':
        for _ in range(days):
            current_height += current_height * 0.03
    elif plant_type == 'C':
        current_height += 2 * days

    return round(current_height, 1)

