def smallest_missing_positive(nums):
    """
    Returns the smallest positive integer (greater than 0) that does not appear in the array.
    """
    n = len(nums)

    # Move each value to the corresponding position of its value
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # Find the first location where the index doesn't match the value
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

