def process_transactions(transactions):
    """
    Processes a list of library transactions to determine the current status of borrowed books.

    Parameters:
    transactions (list of str): List of transaction strings.

    Returns:
    list of str: A list of strings representing the current status of borrowed books.
    """
    borrowed_books = {}

    for transaction in transactions:
        parts = transaction.split()
        action = parts[0]
        book_id = int(parts[1])

        if action == "BORROW":
            patron_name = parts[2]
            borrowed_books[book_id] = patron_name
        elif action == "RETURN":
            if book_id in borrowed_books:
                del borrowed_books[book_id]

    if not borrowed_books:
        return ["No books are currently borrowed."]

    result = [f"{book_id}: {patron_name}" for book_id, patron_name in sorted(borrowed_books.items())]
    return result

