def hiking_trip_markers(M, T, markers, queries):
    """
    Determines if queried sequences of trail markers match any subsequence of documented trail markers.

    M: int - number of trail markers
    T: int - number of queries
    markers: List[str] - list of recorded trail markers
    queries: List[Tuple[int, List[str]]] - list of queries where each query is a tuple of length P and list of markers

    return: List[str] - list of results for each query ("Trail found" or "Trail not found")
    """
    results = []
    for query in queries:
        P, seq = query
        found = False
        for i in range(M - P + 1):
            if markers[i:i+P] == seq:
                found = True
                break
        if found:
            results.append("Trail found")
        else:
            results.append("Trail not found")
    return results

def find_num_disconnected_groups(n, m, photos):
    # Create an adjacency list to represent the graph
    adj_list = {i: set() for i in range(1, n + 1)}

    for photo in photos:
        users = photo[1:]
        for i in range(len(users)):
            for j in range(i + 1, len(users)):
                adj_list[users[i]].add(users[j])
                adj_list[users[j]].add(users[i])

    def dfs(node, visited):
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in adj_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    groups = 0

    for user in range(1, n + 1):
        if user not in visited:
            visited.add(user)
            dfs(user, visited)
            groups += 1

    return groups

