def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_m_largest_primes(sequence, m):
    primes = [num for num in sequence if is_prime(num)]
    if len(primes) < m:
        return -1
    primes.sort(reverse=True)
    return sum(primes[:m])

# Example usage:
# N, m = 10, 3
# sequence = [18, 29, 3, 10, 5, 17, 100, 23, 697, 1]
# print(sum_of_m_largest_primes(sequence, m))  # Output: 69

