def max_shops_and_spending(n, b, prices):
    prices.sort()
    visited_shops = 0
    total_spent = 0

    for price in prices:
        if total_spent + price <= b:
            total_spent += price
            visited_shops += 1
        else:
            break

    return visited_shops, total_spent

