def process_commands(n, commands):
    lst = []
    output = []
    for command in commands:
        parts = command.split()
        cmd = parts[0]
        if cmd == "append":
            lst.append(int(parts[1]))
        elif cmd == "insert":
            lst.insert(int(parts[1]), int(parts[2]))
        elif cmd == "remove":
            lst.remove(int(parts[1]))
        elif cmd == "pop":
            lst.pop()
        elif cmd == "print":
            output.append(lst.copy())
        elif cmd == "reverse":
            lst.reverse()
        elif cmd == "sort":
            lst.sort()
    return output

