def max_customers_segment(n, customers):
    max_sum = 0
    # Iterate through each possible start of the segment
    for i in range(n):
        current_sum = 0
        # Sum the segment starting at i
        for j in range(i, n):
            current_sum += customers[j]
            # Update the max sum if the current one is greater
            if current_sum > max_sum:
                max_sum = current_sum
    return max_sum

