def simulate_cpu(instructions):
    registers = {'A': 0, 'B': 0}

    for instruction in instructions:
        parts = instruction.split()
        op = parts[0]
        reg = parts[1]

        if op == 'SET':
            value = int(parts[2])
            registers[reg] = value

        elif op in ['ADD', 'SUB', 'MUL']:
            reg2 = parts[2]
            if op == 'ADD':
                registers[reg] += registers[reg2]
            elif op == 'SUB':
                registers[reg] -= registers[reg2]
            elif op == 'MUL':
                registers[reg] *= registers[reg2]

    return registers['A'], registers['B']

