def can_rearrange_to_odd_sum_sequence(arr):
    """
    Determines whether an array can be rearranged such that every pair of adjacent numbers has an odd sum.
    If possible, returns "YES" and the rearranged sequence; otherwise, returns "NO".

    :param arr: List of integers.
    :return: Tuple (str, list) with "YES" and the rearranged sequence or "NO".
    """
    n = len(arr)
    odd_numbers = [x for x in arr if x % 2 != 0]
    even_numbers = [x for x in arr if x % 2 == 0]

    if abs(len(odd_numbers) - len(even_numbers)) > 1:
        return ("NO", None)

    if len(odd_numbers) == len(even_numbers):
        return ("YES", [odd_numbers[i // 2] if i % 2 == 0 else even_numbers[i // 2] for i in range(n)])

    if len(odd_numbers) > len(even_numbers):
        rearranged = [odd_numbers[0]]
        odd_numbers = odd_numbers[1:]
    else:
        rearranged = [even_numbers[0]]
        even_numbers = even_numbers[1:]

    while odd_numbers and even_numbers:
        rearranged.append(even_numbers.pop(0))
        rearranged.append(odd_numbers.pop(0))

    if odd_numbers:
        rearranged.append(odd_numbers.pop(0))
    if even_numbers:
        rearranged.append(even_numbers.pop(0))

    return ("YES", rearranged)

import heapq

def shortest_travel_time(N, M, roads, Q, paths):
    # Create the graph as a dictionary of adjacency lists
    graph = {i: [] for i in range(1, N+1)}
    for u, v, t in roads:
        graph[u].append((v, t))
        graph[v].append((u, t))

    def dijkstra(start, end):
        # Priority queue for Dijkstra
        pq = [(0, start)]
        dist = {i: float('inf') for i in range(1, N+1)}
        dist[start] = 0

        while pq:
            current_dist, node = heapq.heappop(pq)

            if node == end:
                return current_dist

            if current_dist > dist[node]:
                continue

            for neighbor, weight in graph[node]:
                distance = current_dist + weight

                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))

        return -1  # if no path from start to end

    results = []
    for a, b in paths:
        results.append(dijkstra(a, b))

    return results

