def is_valid_rgb_pattern(s):
    """
    Returns "VALID" if the string can be rearranged to form a valid RGB pattern, else "INVALID".
    """
    if len(s) % 3 != 0:
        return "INVALID"

    count_R = s.count('R')
    count_G = s.count('G')
    count_B = s.count('B')

    if count_R == count_G == count_B:
        return "VALID"
    else:
        return "INVALID"

def find_path_with_treasures(grid):
    from queue import PriorityQueue

    direction = [(0, 1), (1, 0)]  # right, down
    n = len(grid)
    visited = [[False] * n for _ in range(n)]

    pq = PriorityQueue()
    pq.put((-int(grid[0][0] == 'T'), [(0, 0)]))  # store negative treasure count for max heap

    while not pq.empty():
        neg_treasures, path = pq.get()
        x, y = path[-1]
        treasures = -neg_treasures

        if (x, y) == (n-1, n-1):
            return path

        for dx, dy in direction:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] != '#':
                visited[nx][ny] = True
                if grid[nx][ny] == 'T':
                    pq.put((-(treasures + 1), path + [(nx, ny)]))
                else:
                    pq.put((-treasures, path + [(nx, ny)]))

    return "Not Possible"

