def min_changes_to_palindrome(s):
    """
    Returns the minimum number of changes needed to convert the given string into a palindrome.
    """
    n = len(s)
    changes = 0
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            changes += 1
    return changes

