from functools import lru_cache

def lcs(strs):
    """
    Finds the length of the longest common subsequence among the given binary strings.
    """
    # Perform pairwise LCS calculation
    @lru_cache(None)
    def lcs_2str(s1, s2):
        m, n = len(s1), len(s2)
        # Creating a 2D array to store lengths of longest common subsequence.
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m+1):
            for j in range(n+1):
                if i == 0 or j == 0:
                    dp[i][j] = 0
                elif s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        return dp[m][n]

    lcs_length = len(strs[0])
    for i in range(1, len(strs)):
        lcs_length = lcs_2str(strs[0][:lcs_length], strs[i])
        if lcs_length == 0:
            return 0

    return lcs_length

