def is_toeplitz(matrix, n, m):
    """
    Check if the given n x m matrix is a Toeplitz matrix.
    """
    for i in range(1, n):
        for j in range(1, m):
            if matrix[i][j] != matrix[i - 1][j - 1]:
                return "NO"
    return "YES"

def check_toeplitz_matrices(test_cases):
