def can_form_palindrome(words):
    """
    Given a list of words, determine if each word can be rearranged to form a palindrome.

    :param words: List of words to check
    :return: List of "YES" or "NO" for each word
    """
    results = []
    for word in words:
        char_count = {}
        for char in word:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        odd_count = 0
        for count in char_count.values():
            if count % 2 != 0:
                odd_count += 1

        if odd_count > 1:
            results.append("NO")
        else:
            results.append("YES")

    return results

from collections import deque, defaultdict
import sys

def find_central_computers(n, m, connections):
    def bfs(start):
        distances = [-1] * n
        distances[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in adj_list[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    queue.append(neighbor)
        return distances

    adj_list = defaultdict(list)
    for u, v in connections:
        adj_list[u - 1].append(v - 1)
        adj_list[v - 1].append(u - 1)

    all_distances = []
    for i in range(n):
        distances = bfs(i)
        all_distances.append((max(distances), i))

    all_distances.sort()
    min_distance = all_distances[0][0]
    central_computers = [i + 1 for d, i in all_distances if d == min_distance]

    if len(central_computers) < 2:
        return "-1"
    else:
        return " ".join(map(str, sorted(central_computers)))

def solve(t, cases):
    results = []
    for n, m, connections in cases:
        result = find_central_computers(n, m, connections)
        results.append(result)
    return results

import sys
from collections import defaultdict, deque

def minimum_royal_guards(n, m, roads):
    def bfs(start, visited, graph):
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    if n == 0:
        return 0

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    count = 0

    for i in range(1, n + 1):
        if not visited[i]:
            count += 1
            visited[i] = True
            bfs(i, visited, graph)

    return count

