    """
    Determines if the sequence of runes (s) can be found in the grid following the movement rules.

    :param n: Number of rows in the grid
    :param m: Number of columns in the grid
    :param grid: List of strings representing the grid
    :param s: Sequence of runes to be followed
    :return: "YES" if the sequence can be followed, otherwise "NO"
    """
    def dfs(x, y, index):
        if index == len(s):
            return True  # if all characters are checked

        if not (0 <= x < n and 0 <= y < m) or grid[x][y] != s[index]:
            return False  # boundary check and mismatch

        # temporarily mark the current cell to avoid revisiting
        temp = grid[x][y]
        grid[x] = grid[x][:y] + "#" + grid[x][y+1:]

        # explore all possible directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dfs(x + dx, y + dy, index + 1):
                return True

        # backtrack to restore the original cell
        grid[x] = grid[x][:y] + temp + grid[x][y+1:]
        return False

    # start DFS from each cell that matches the first rune
    for i in range(n):
        for j in range(m):
            if grid[i][j] == s[0]:
                if dfs(i, j, 0):
                    return "YES"

    return "NO"

def can_thief_steal_exactly_k_days(n, k, heaps):
    total_treasures = sum(heaps)  # sum of all treasures in heaps
    max_nights = (k * (k + 1)) // 2  # sum of first k integers

    # We need at least k treasures to be stolen over k days:
    if total_treasures < k:
        return "NO"

    # We need that total number of nights we can potentially fulfill is at least k:
    if max_nights <= total_treasures:
        return "YES"
    else:
        return "NO"

