def are_points_collinear(n, coordinates):
    def on_same_line(p1, p2, p3):
        # Check if three points (p1, p2, p3) are collinear using the cross product method
        return (p2[1] - p1[1]) * (p3[0] - p1[0]) == (p3[1] - p1[1]) * (p2[0] - p1[0])

    for i in range(n):
        for j in range(i + 1, n):
            count = 2  # Two points (i, j) are initially assumed to be collinear
            for k in range(j + 1, n):
                if on_same_line(coordinates[i], coordinates[j], coordinates[k]):
                    count += 1
                    if count >= 3:
                        return "YES"
    return "NO"

