def can_form_secret_words(n, secret_words, q, group_codes):
    sorted_secret_words = {"".join(sorted(word)) for word in secret_words}
    results = []

    for code in group_codes:
        sorted_code = "".join(sorted(code))
        if sorted_code in sorted_secret_words:
            results.append("YES")
        else:
            results.append("NO")

    return results

