def possible_flower_state(n, m, observations):
    from itertools import combinations

    # Brute force: try all possible states and check all observations
    for bits in combinations(range(n), m):
        test_state = [0] * n
        for bit in bits:
            test_state[bit] = 1

        valid = True
        for l, r, k in observations:
            if sum(test_state[l-1:r]) != k:
                valid = False
                break

        if valid:
            return ''.join(map(str, test_state))

    return -1

