from collections import defaultdict, deque

def can_travel(graph, n, start, end, min_capacity):
    visited = set()
    queue = deque([start])

    while queue:
        current = queue.popleft()
        if current == end:
            return True
        if current not in visited:
            visited.add(current)
            for neighbor, capacity in graph[current]:
                if capacity >= min_capacity and neighbor not in visited:
                    queue.append(neighbor)

    return False

def process_queries(n, m, edges, q, queries):
    max_capacity = 1000000
    graph = defaultdict(list)

    for u, v, w in edges:
        if w > 0:
            graph[u].append((v, w))

    results = []
    for a, b, c in queries:
        if can_travel(graph, n, a, b, c):
            results.append("YES")
        else:
            results.append("NO")

    return results

