from collections import deque

def can_meet_at_checkpoint(n, m, k, edges, start_positions, checkpoint):
    def bfs(start, graph, n):
        visited = set()
        queue = deque([start])
        while queue:
            vertex = queue.popleft()
            if vertex not in visited:
                visited.add(vertex)
                queue.extend([neighbor for neighbor in graph[vertex] if neighbor not in visited])
        return visited

    # Create the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Check if all starting positions can reach the checkpoint
    reachable_from_checkpoint = bfs(checkpoint, graph, n)

    for pos in start_positions:
        if pos not in reachable_from_checkpoint:
            return "NO"
    return "YES"

