def longest_path_unique_letters(n, m, grid):
    def dfs(x, y, visited):
        max_path_len = len(visited)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] not in visited:
                visited.add(grid[nx][ny])
                max_path_len = max(max_path_len, dfs(nx, ny, visited))
                visited.remove(grid[nx][ny])
        return max_path_len

    max_length = 0
    for i in range(n):
        for j in range(m):
            visited = set(grid[i][j])
            max_length = max(max_length, dfs(i, j, visited))

    return max_length

def max_projects(n, m, projects, scientists):
    from collections import defaultdict
    from itertools import permutations

    def can_do_project(scientist_skills, project_skills):
        return all(skill in scientist_skills for skill in project_skills)

    project_requirements = [set(project[1:]) for project in projects]
    scientist_skills = [set(scientist[1:]) for scientist in scientists]

    matches = defaultdict(list)

    for p_idx, project in enumerate(project_requirements):
        for s_idx, scientist in enumerate(scientist_skills):
            if can_do_project(scientist, project):
                matches[p_idx].append(s_idx)

    # Use maximum bipartite matching algorithm
    def bpm(u, matchR, seen):
        for v in matches[u]:
            if not seen[v]:
                seen[v] = True
                if matchR[v] == -1 or bpm(matchR[v], matchR, seen):
                    matchR[v] = u
                    return True
        return False

    matchR = [-1] * n

    result = 0
    for i in range(m):
        seen = [False] * n
        if bpm(i, matchR, seen):
            result += 1

    return result

def max_contiguous_submatrix(matrix, n, m, k):
    max_blocks = 0
    for color in range(1, k + 1):
        block_count = [[0] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                if matrix[i][j] == color:
                    block_count[i][j] = 1
                    if i > 0:
                        block_count[i][j] += block_count[i - 1][j]

        for top in range(n):
            for bottom in range(top, n):
                width_count = {0: -1}
                width_sum = 0
                for col in range(m):
                    height = bottom - top + 1
                    if block_count[bottom][col] >= height:
                        width_sum += 1
                    else:
                        width_sum = 0

                    if width_sum > 0:
                        max_blocks = max(max_blocks, width_sum * height)

    return max_blocks

def bellman_ford(n, m, s, edges):
    import sys
    INF = sys.maxsize

    # Initialize the distance to all vertices as infinity
    distance = [INF] * n
    distance[s - 1] = 0  # Distance to the source is 0

    # Relax the edges up to n-1 times
    for _ in range(n - 1):
        for u, v, w in edges:
            if distance[u - 1] != INF and distance[u - 1] + w < distance[v - 1]:
                distance[v - 1] = distance[u - 1] + w

    # Check for negative-weight cycles
    for u, v, w in edges:
        if distance[u - 1] != INF and distance[u - 1] + w < distance[v - 1]:
            return "Negative weight cycle detected"

    # Format the result
    result = []
    for i in range(n):
        if distance[i] == INF:
            result.append("UNREACHABLE")
        else:
            result.append(distance[i])

    return result

def substring_palindrome_check(strings, queries):
    results = []
    for s, e in queries:
        substr = strings[s][e[0]:e[1]+1]
        if substr == substr[::-1]:
            results.append(1)
        else:
            results.append(0)
    return results

from collections import deque

def calculate_shortest_path(n, m, grid):
    if grid[0][0] == -1 or grid[n-1][m-1] == -1:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == n-1 and y == m-1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] != -1:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

