def min_seconds_to_reach(h, w, grid, sx, sy, tx, ty):
    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w and grid[x][y] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)] # up, down, left, right
    queue = deque([(sx, sy, 0)]) # (x, y, distance)
    visited = set()
    visited.add((sx, sy))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (tx, ty):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

