def judge_circle(moves: str) -> bool:
    """
    Determines if a sequence of moves will cause the robot to return to its starting point (0, 0).

    Parameters:
    moves (str): A string containing the sequence of moves, which can only be characters 'U', 'D', 'L', 'R'.

    Returns:
    bool: True if the sequence of moves brings the robot back to the origin, False otherwise.
    """
    x, y = 0, 0

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return x == 0 and y == 0

def search_first_and_last_occurrence(array, query):
    """
    Returns a tuple containing the indices of the first and last occurrence
    of the query element in the array. If the element is not found, returns (-1, -1).
    """
    first_occurrence = -1
    last_occurrence = -1

    for i in range(len(array)):
        if array[i] == query:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    return (first_occurrence, last_occurrence)

