from typing import List

def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    while right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if mid1 >= len(arr) or mid2 >= len(arr):
            return -1

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

