def find_path(graph: dict, start: str, end: str) -> list:
    """
    Finds any path between start and end nodes in an undirected graph.
    """
    def dfs(current, target, path, visited):
        if current == target:
            return path
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                result = dfs(neighbor, target, path + [neighbor], visited)
                if result is not None:
                    return result
        return None

    return dfs(start, end, [start], set())

def find_shortest_path(graph: dict, start: str, end: str) -> list:
    """
    Finds the shortest path between start and end nodes in an undirected graph.
    """
    from collections import deque

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        current, path = queue.popleft()
        if current == end:
            return path
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    return None

