import math

def enhanced_prime_check(n: int) -> bool:
    """
    Determines if a number is a prime.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    if n > 10**6:
        # Advanced check for large numbers
        if n % 5 == 0 or n % 7 == 0:
            return False

    i = 5
    while (i * i) <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

def get_insert_position(arr, target):
    """
    Returns the index where the target should be inserted in the sorted
    array to maintain the order. If the target is already in the array,
    its current index is returned.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

