def int_to_base(num, base):
    if not (2 <= base <= 36):
        raise ValueError("Base must be between 2 and 36 (inclusive)")

    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if num == 0:
        return "0"

    sign = "-" if num < 0 else ""
    num = abs(num)
    result = []

    while num > 0:
        result.append(chars[num % base])
        num //= base

    return sign + "".join(reversed(result))


def base_to_int(str_to_convert, base):
    if not (2 <= base <= 36):
        raise ValueError("Base must be between 2 and 36 (inclusive)")

    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    str_to_convert = str_to_convert.upper()

    sign = -1 if str_to_convert[0] == '-' else 1
    str_to_convert = str_to_convert.lstrip('-')

    num = 0
    for char in str_to_convert:
        num = num * base + chars.index(char)

    return sign * num

from typing import List, Tuple

def matrix_chain_order(array: List[int]) -> Tuple[int, List[List[int]]]:
    n = len(array)
    m = [[0] * n for _ in range(n)]
    s = [[0] * n for _ in range(n)]

    for l in range(2, n):
        for i in range(1, n - l + 1):
            j = i + l - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + array[i - 1] * array[k] * array[j]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m[1][n - 1], s

