def extended_gcd(num1: int, num2: int) -> (int, int, int):
    """
    Returns the coefficients (s, t) and the GCD (g) of num1 and num2 such that:
    num1 * s + num2 * t = g
    """
    if num2 == 0:
        return (1, 0, num1)
    else:
        s, t, g = extended_gcd(num2, num1 % num2)
        return (t, s - (num1 // num2) * t, g)

import math

def calculate_third_side(opposite, adjacent, hypotenuse):
    """
    Calculate the missing side length of a right-angled triangle using the Pythagorean theorem.

    Parameters:
    opposite (float or str): Length of the opposite side, or "?" if unknown.
    adjacent (float or str): Length of the adjacent side, or "?" if unknown.
    hypotenuse (float or str): Length of the hypotenuse side, or "?" if unknown.

    Returns:
    str: A string indicating the calculated length of the missing side.

    Raises:
    ValueError: If invalid arguments are provided or the inputs do not form a valid right-angled triangle.
    """
    if opposite == "?":
        if isinstance(adjacent, (float, int)) and isinstance(hypotenuse, (float, int)) and hypotenuse > adjacent:
            opposite = math.sqrt(hypotenuse**2 - adjacent**2)
            return f"Opposite = {opposite:.1f}"
        else:
            raise ValueError("Invalid input values.")

    elif adjacent == "?":
        if isinstance(opposite, (float, int)) and isinstance(hypotenuse, (float, int)) and hypotenuse > opposite:
            adjacent = math.sqrt(hypotenuse**2 - opposite**2)
            return f"Adjacent = {adjacent:.1f}"
        else:
            raise ValueError("Invalid input values.")

    elif hypotenuse == "?":
        if isinstance(opposite, (float, int)) and isinstance(adjacent, (float, int)):
            hypotenuse = math.sqrt(opposite**2 + adjacent**2)
            return f"Hypotenuse = {hypotenuse:.1f}"
        else:
            raise ValueError("Invalid input values.")

    else:
        raise ValueError("Only one side must be unknown.")

