from typing import List

def summarize_ranges(array: List[int]) -> List[str]:
    """
    Summarizes a sorted list of integers into a list of ranges.

    Parameters:
    - array: List[int] - a sorted list of unique integers.

    Returns:
    - List[str]: a list of string representations of summarized ranges.
    """
    if not array:
        return []

    ranges = []
    start = array[0]
    end = array[0]

    for i in range(1, len(array)):
        if array[i] == end + 1:
            end = array[i]
        else:
            if start == end:
                ranges.append(f"{start}")
            else:
                ranges.append(f"{start}-{end}")
            start = array[i]
            end = array[i]

    if start == end:
        ranges.append(f"{start}")
    else:
        ranges.append(f"{start}-{end}")

    return ranges

