from typing import List

def binary_search_extended(array: List[int], query: int) -> int:
    def find_left_index():
        lo, hi = 0, len(array)
        while lo < hi:
            mid = (lo + hi) // 2
            if array[mid] < query:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def find_right_index():
        lo, hi = 0, len(array)
        while lo < hi:
            mid = (lo + hi) // 2
            if array[mid] <= query:
                lo = mid + 1
            else:
                hi = mid
        return lo

    left_index = find_left_index()
    right_index = find_right_index()

    if left_index == len(array) or array[left_index] != query:
        return 0
    return right_index - left_index

