def pattern_match(pattern: str, string: str) -> bool:
    def is_match(p_idx, s_idx, mapping, used):
        if p_idx == len(pattern) and s_idx == len(string):
            return True
        if p_idx == len(pattern) or s_idx == len(string):
            return False

        char = pattern[p_idx]

        if char in mapping:
            word = mapping[char]
            if string.startswith(word, s_idx):
                return is_match(p_idx + 1, s_idx + len(word), mapping, used)
            return False

        for end in range(s_idx + 1, len(string) + 1):
            word = string[s_idx:end]
            if word in used:
                continue

            mapping[char] = word
            used.add(word)
            if is_match(p_idx + 1, s_idx + len(word), mapping, used):
                return True
            del mapping[char]
            used.remove(word)

        return False

    return is_match(0, 0, {}, set())

