def cycle_sort(arr):
    """
    Sorts an array in place using Cycle Sort algorithm and returns it.
    """
    n = len(arr)

    # Loop through the array to find cycles to rotate
    for cycle_start in range(0, n - 1):
        item = arr[cycle_start]

        # Find the location where to put the item
        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Skip duplicates
        while item == arr[pos]:
            pos += 1

        # Put the item to the correct position
        if pos != cycle_start:
            arr[pos], item = item, arr[pos]

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            if item != arr[pos]:
                arr[pos], item = item, arr[pos]

    return arr

