def heap_sort_max(arr, k):
    import heapq

    def max_heapify(heap):
        return [-x for x in heap]

    def print_array(interval, array):
        if interval % k == 0:
            print(f"Iteration {interval}: {array}")

    arr = max_heapify(arr)

    heapq.heapify(arr)
    sorted_array = []
    interval = 0

    while arr:
        sorted_array.append(-heapq.heappop(arr))
        interval += 1
        print_array(interval, [-x for x in arr])

    return sorted_array

def heap_sort_min(arr, k):
    import heapq

    def print_array(interval, array):
        if interval % k == 0:
            print(f"Iteration {interval}: {array}")

    heapq.heapify(arr)
    sorted_array = []
    interval = 0

    while arr:
        sorted_array.append(heapq.heappop(arr))
        interval += 1
        print_array(interval, arr)

    return sorted_array

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    # dp[i][j] will be True if s[:i] matches p[:j], else False
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty string matches with empty pattern
    dp[0][0] = True

    # Populate for patterns with '*' that can match 0 preceding character
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                # Match a single character
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                # Match zero or more of the preceding character
                dp[i][j] = dp[i][j - 2] or ((p[j - 2] == s[i - 1] or p[j - 2] == '.') and dp[i - 1][j])

    return dp[m][n]

