def judge_circle(moves: str) -> bool:
    """
    Determines if a sequence of robot moves returns the robot to its original position.
    """
    # Initial positions
    if not all(move in "RLUD" for move in moves):
        return False

    x, y = 0, 0

    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    # Checking final position
    return x == 0 and y == 0

def unique_chars_preserved_order(s: str) -> str:
    """
    Returns a new string containing only the first occurrence of each character from the input string s,
    preserving their original order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

