def is_match(s: str, p: str) -> bool:
    """
    Checks if the input string `s` matches the pattern `p`.
    """
    # dp[i][j] will be True if the first i characters in s can match
    # the first j characters in p
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Base case: empty string matches empty pattern
    dp[0][0] = True

    # Handle patterns like a* or a*b* or a*b*c* which can match empty string
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (p[j - 2] == s[i - 1] or p[j - 2] == '.'))

    return dp[len(s)][len(p)]

