from typing import List, Dict, Any

def topological_sort(graph: Dict[Any, List[Any]]) -> List[Any]:
    # Helper function to perform Depth-First Search (DFS)
    def dfs(node):
        if visited[node] == -1:
            raise ValueError("Graph is not a DAG")
        if visited[node] == 0:
            visited[node] = -1
            for neighbor in graph.get(node, []):
                dfs(neighbor)
            visited[node] = 1
            result.append(node)

    visited = {node: 0 for node in graph}
    result = []
    for node in graph:
        if visited[node] == 0:
            dfs(node)
    result.reverse()
    return result

