from typing import List, Union

def enhanced_insertion_sort(arr: List[Union[int, float]]) -> List[Union[int, float]]:
    if not arr:
        return arr

    # Check if array is already sorted
    is_sorted = all(arr[i] <= arr[i+1] for i in range(len(arr) - 1))
    if is_sorted:
        return arr

    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

    return arr

