from xml.parsers.expat import ParserCreate, ExpatError

def parse_books(xml_data):
    current_book = None
    current_element = None
    books = []

    def start_element(name, attrs):
        nonlocal current_book, current_element
        if name == 'book':
            current_book = {}
        current_element = name

    def end_element(name):
        nonlocal current_book, current_element
        if name == 'book':
            books.append(current_book)
            current_book = None
        current_element = None

    def char_data(data):
        nonlocal current_book, current_element
        if current_book is not None and current_element is not None:
            if current_element in current_book:
                current_book[current_element] += data.strip()
            else:
                current_book[current_element] = data.strip()

    parser = ParserCreate()
    parser.StartElementHandler = start_element
    parser.EndElementHandler = end_element
    parser.CharacterDataHandler = char_data

    try:
        parser.Parse(xml_data)
    except ExpatError as e:
        print(f"XML parsing error: {e}")
        return

    for book in books:
        print(f"Title: {book.get('title', '')}")
        print(f"Author: {book.get('author', '')}")
        print(f"Year: {book.get('year', '')}")
        if 'description' in book:
            print(f"Description: {book.get('description', '')}")

from functools import lru_cache

@lru_cache(maxsize=None)
def partition_count(n: int) -> int:
    """
    Computes the number of ways to partition the integer n
    using memoization to optimize redundant calculations.
    """
    # Base case
    if n == 0:
        return 1

    count = 0
    for i in range(1, n + 1):
        count += partition_count(n - i)

    return count

# Improve the computation logic by using a correct combinatorial approach
def partition_count(n: int) -> int:
    @lru_cache(maxsize=None)
    def partitions(k, max_val):
        if k == 0:
            return 1
        if k < 0 or max_val == 0:
            return 0
        return partitions(k, max_val - 1) + partitions(k - max_val, max_val)

    return partitions(n, n) - 1  # Subtracting 1 to exclude the partition where n is a single part

