import shlex

def shell_split(command: str) -> list:
    """
    Split the command string into a list of tokens using shell-like syntax.
    """
    return shlex.split(command, posix=True)

def shell_join(tokens: list) -> str:
    """
    Join a list of command tokens back into a string with proper shell escaping.
    """
    return ' '.join(shlex.quote(token) for token in tokens)

def shell_quote(token: str) -> str:
    """
    Return a shell-escaped version of the string token.
    """
    return shlex.quote(token)

