def filter_unique_primes(numbers):
    """
    Returns a list of unique prime numbers from the input list.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    unique_numbers = set(numbers)
    prime_numbers = [num for num in unique_numbers if is_prime(num)]
    return sorted(prime_numbers)

