import re

def classify_emails(emails, spam_keywords):
    classifications = []
    for email in emails:
        spam = False
        for keyword in spam_keywords:
            if re.search(keyword, email, re.IGNORECASE):
                classifications.append("spam")
                spam = True
                break
        if not spam:
            classifications.append("not spam")
    return classifications

def is_prime(n):
    """
    Helper function to determine if a number n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def filter_primes(numbers):
    """
    Returns a list of prime numbers from the input list of integers.
    """
    return [num for num in numbers if is_prime(num)]

