from typing import List

def find_peak(nums: List[int]) -> int:
    """
    Returns a peak element from the given list of integers.
    A peak element is greater than its neighbors. For corner elements, we need to consider only one neighbor.
    """
    # If the list has only one element, return it
    if len(nums) == 1:
        return nums[0]

    # Helper function to find peak recursively using binary search approach
    def find_peak_util(nums, low, high):
        # Find the mid index
        mid = low + (high - low) // 2

        # Compare middle element with its neighbours (if neighbours exist)
        if (mid == 0 or nums[mid - 1] <= nums[mid]) and (mid == len(nums) - 1 or nums[mid + 1] <= nums[mid]):
            return nums[mid]
        # If the left neighbor of mid is greater than mid, then there is a peak element on the left half
        elif mid > 0 and nums[mid - 1] > nums[mid]:
            return find_peak_util(nums, low, mid - 1)
        # If the right neighbor of mid is greater than mid, then there is a peak element on the right half
        else:
            return find_peak_util(nums, mid + 1, high)

    return find_peak_util(nums, 0, len(nums) - 1)

