def remove_duplicates(input_string):
    """
    Returns a new string where all duplicate characters have been removed.
    The order of characters in the new string is the same as they first appear in the input string.
    """
    seen = set()
    result = []
    for char in input_string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

