def find_pair(arr, target):
    """
    Returns the first pair of elements from arr that add up to the target sum.
    Utilizes a dictionary to improve the performance to O(n) time complexity.
    """
    seen = {}
    for num in arr:
        complement = target - num
        if complement in seen:
            return [complement, num]
        seen[num] = True
    return None

