def num_uniques(list_of_lists):
    """
    Returns a dictionary where the keys are the numbers from the sublists and the values
    are the counts of how many sublists each number is in.
    """
    unique_counts = {}

    for sublist in list_of_lists:
        seen_in_current_sublist = set()
        for number in sublist:
            if number not in seen_in_current_sublist:
                if number not in unique_counts:
                    unique_counts[number] = 0
                unique_counts[number] += 1
                seen_in_current_sublist.add(number)

    return unique_counts

