def check_blacklisted_items(orders, blacklisted_items):
    """
    This function checks if orders contain any blacklisted items.
    It returns a dictionary where each key is the index of the order,
    and the value is a list of blacklisted items found in that order.

    :param orders: List of orders where each order is a dictionary containing 'items'.
    :param blacklisted_items: List of item names that are blacklisted.
    :return: A dictionary with order indices as keys and lists of blacklisted items as values.
    """
    return {
        i: [
            item['item_name']
            for item in order['items']
            if item['item_name'] in blacklisted_items
        ]
        for i, order in enumerate(orders)
        if any(item['item_name'] in blacklisted_items for item in order['items'])
    }

