def is_match(s, p):
    """
    Returns True if string s matches pattern p with wildcards
    '?' and '*', otherwise False.
    """
    m, n = len(s), len(p)
    # dp table with default value of False
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    # empty pattern matches empty string
    dp[0][0] = True

    # Initialize dp for patterns with '*' at the beginning
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]

