def max_profit(prices):
    """
    Returns the maximum profit that can be made by buying and selling one share of the stock.
    :param prices: List of stock prices over a certain period of time.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

