def length_of_LIS(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize DP array with 1 since each element is an increasing subsequence of length 1

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

