def fibonacci(n):
    """
    Returns the n-th Fibonacci number using recursion.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return add(fibonacci(n-1), fibonacci(n-2))

