def are_anagrams(str1, str2):
    """
    Returns True if str1 and str2 are anagrams of each other, False otherwise.
    """

    # Early return if lengths are not equal
    if len(str1) != len(str2):
        return False

    # Dictionary to count frequency of characters in str1
    count1 = {}
    for char in str1:
        count1[char] = count1.get(char, 0) + 1

    # Dictionary to count frequency of characters in str2
    count2 = {}
    for char in str2:
        count2[char] = count2.get(char, 0) + 1

    # Compare both dictionaries
    return count1 == count2

