def sortColors(nums):
    """
    Sort the input list of colors (represented as 0, 1, 2) in-place without using extra space.
    """
    # Initialize pointers for current element, and the boundaries for 0 and 2
    low, mid, high = 0, 0, len(nums) - 1

    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[high], nums[mid] = nums[mid], nums[high]
            high -= 1

def square_values(input_dict):
    """
    Takes a dictionary as input and returns a new dictionary with the values squared.
    Raises ValueError if any of the values are not integers or if any of the values are negative.
    """
    output_dict = {}
    for key, value in input_dict.items():
        if not isinstance(value, int):
            raise ValueError(f"Value for key '{key}' is not an integer.")
        if value < 0:
            raise ValueError(f"Value for key '{key}' is negative.")
        output_dict[key] = value ** 2
    return output_dict

