def replace_last_element(lst, new_element):
    """
    Replaces the last element in a list with a new given element.
    If the list is empty, it simply returns the list with the new element added.
    """
    if len(lst) == 0:
        return [new_element]

    result = []
    for i in range(len(lst)):
        if i == len(lst) - 1:
            result.append(new_element)
        else:
            result.append(lst[i])

    return result

