def find_last_char(str1, str2):
    """
    Returns the last character in str1 that is present in str2 along with its index in str1.
    If no such character is found, returns (None, None).
    """
    last_char = None
    last_index = None
    for i in range(len(str1)):
        if str1[i] in str2:
            last_char = str1[i]
            last_index = i
    return (last_char, last_index)

