from collections import defaultdict

def detect_language(sample):
    english_words = {"the", "hello", "world", "and", "is", "in", "this", "you", "are", "program"}
    spanish_words = {"el", "hola", "mundo", "y", "es", "en", "este", "tu", "eres", "programa"}
    french_words = {"le", "bonjour", "monde", "et", "est", "dans", "ceci", "tu", "es", "programme"}

    english_count = sum(word in english_words for word in sample.split())
    spanish_count = sum(word in spanish_words for word in sample.split())
    french_count = sum(word in french_words for word in sample.split())

    if spanish_count > english_count and spanish_count > french_count:
        return 'spanish'
    elif french_count > english_count and french_count > spanish_count:
        return 'french'
    else:
        return 'english'

def sort_dictionary_by_language(d):
    categorized_strings = defaultdict(list)

    for key, val in d.items():
        language = detect_language(val)
        categorized_strings[language].append(val)

    for lang in categorized_strings:
        categorized_strings[lang].sort()

    return dict(categorized_strings)

