def generate_checkerboard(length, width):
    """
    Generates an ASCII checkerboard pattern of given length and width.

    Args:
    length (int): The length of the checkerboard.
    width (int): The width of the checkerboard.

    Returns:
    str: The checkerboard pattern as a string.
    """
    checkerboard = []
    for i in range(length):
        row = []
        for j in range(width):
            if (i + j) % 2 == 0:
                row.append('X')
            else:
                row.append('O')
        checkerboard.append(''.join(row))
    return '\n'.join(checkerboard)

