def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def primes_with_indices(numbers):
    """
    Returns a dictionary with prime numbers as keys and their indices from the input list as values.
    """
    if not all(isinstance(num, int) and num > 0 for num in numbers):
        raise ValueError("The list should only contain positive integers")

    return {num: idx for idx, num in enumerate(numbers) if is_prime(num)}

