def find_second_smallest(numbers):
    """
    Returns the second smallest element in a list of numbers.
    If the list has fewer than 2 unique elements, returns None.
    """
    if len(numbers) < 2:
        return None

    first_min = second_min = float('inf')
    for num in numbers:
        if num < first_min:
            second_min = first_min
            first_min = num
        elif first_min < num < second_min:
            second_min = num

    return second_min if second_min != float('inf') else None

