import heapq

def dijkstra(graph, start, end):
    """
    Calculate the shortest path between the start and end nodes using Dijkstra's algorithm.

    :param graph: A dictionary where keys are node labels and values are dictionaries
                  of neighboring node labels and edge weights.
    :param start: The starting node label.
    :param end: The ending node label.
    :return: The shortest path and its total weight as a tuple (path, weight).
    """
    priority_queue = [(0, start, [])]  # (cost, current_node, path)
    visited = set()
    min_distances = {start: 0}

    while priority_queue:
        current_cost, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        path = path + [current_node]
        visited.add(current_node)

        if current_node == end:
            return (path, current_cost)

        for neighbor, weight in graph[current_node].items():
            if neighbor not in visited:
                old_cost = min_distances.get(neighbor, float('inf'))
                new_cost = current_cost + weight
                if new_cost < old_cost:
                    min_distances[neighbor] = new_cost
                    heapq.heappush(priority_queue, (new_cost, neighbor, path))

    return ([], float('inf'))  # In case there is no path from start to end

