def find_anagrams(word_list):
    """
    Returns a list that contains only the strings that are anagrams of each other.
    """
    anagram_groups = {}
    for word in word_list:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_groups:
            anagram_groups[sorted_word].append(word)
        else:
            anagram_groups[sorted_word] = [word]

    result = [word for words in anagram_groups.values() if len(words) > 1 for word in words]
    return result

