def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in a case-insensitive manner.
    """
    # Create a dictionary to store frequency of each character
    char_count = {}

    # Convert to lowercase for case-insensitive comparison
    for char in s:
        char_lc = char.lower()
        if char_lc in char_count:
            char_count[char_lc] += 1
        else:
            char_count[char_lc] = 1

    # Find the first non-repeating character
    for char in s:
        if char_count[char.lower()] == 1:
            return char

    return None

