def remove_adjacent_duplicates(s):
    """
    Given a string, this function removes all adjacent duplicate characters.

    Args:
    s (str): The input string.

    Returns:
    str: The resulting string with adjacent duplicates removed.
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return ''.join(stack)

