def create_triangle_pattern(rows):
    """
    Returns a triangle pattern with the character '$', with the pattern in reverse order for even rows.
    """
    pattern = []
    for i in range(1, rows + 1):
        line = '$' * i
        pattern.append(line)

    if rows % 2 == 0:
        pattern.reverse()

    return '\n'.join(pattern)

