def find_highest_with_index(lst):
    """
    Finds the highest number in a given list and its index position.
    Ignores non-numeric data and returns the result as a tuple of the form (highest number, index).
    """
    if not lst:
        return (None, -1)

    highest = None
    index = -1

    for i, value in enumerate(lst):
        if isinstance(value, (int, float)):
            if highest is None or value > highest:
                highest = value
                index = i

    return (highest, index)

