def second_largest(numbers):
    """
    Returns the second largest number in the list. If the list does not contain
    at least two distinct numbers, returns None. Handles potential errors.
    """
    if not isinstance(numbers, list):
        raise ValueError("Input should be a list.")

    distinct_numbers = set()  # Use a set to store unique numbers

    for num in numbers:
        if isinstance(num, (int, float)):
            distinct_numbers.add(num)
        else:
            raise ValueError("List should contain only numeric values.")

    if len(distinct_numbers) < 2:
        return None

    largest = max(distinct_numbers)
    distinct_numbers.remove(largest)

    return max(distinct_numbers)

