import cmath

def solve_quadratic(a, b, c):
    """
    Solves the quadratic equation ax^2 + bx + c = 0.

    Parameters:
        a (float): Coefficient of x^2
        b (float): Coefficient of x
        c (float): Constant

    Returns:
        tuple or str: roots of the equation or a message indicating no real roots.
    """
    if a == 0:
        if b != 0:
            return (-c / b,)
        elif c == 0:
            return ("All numbers are solutions.",)
        else:
            return ("No solution.",)

    discriminant = b**2 - 4*a*c
    if discriminant > 0:
        root1 = (-b + discriminant**0.5) / (2*a)
        root2 = (-b - discriminant**0.5) / (2*a)
        return (root1, root2)
    elif discriminant == 0:
        root = -b / (2*a)
        return (root,)
    else:
        return ("No real roots.",)

