def kmp_search(pattern, text):
    """
    Returns the starting index of the first occurrence of the pattern in the text.
    If the pattern is not found, returns -1.
    """

    if not pattern:
        return 0 if text else -1  # Edge case: Empty pattern

    # Preprocess the pattern to get the longest prefix suffix (LPS) array
    lps = [0] * len(pattern)  # Initialize LPS array with zeros
    j = 0  # length of the previous longest prefix suffix
    i = 1

    # Build the LPS array
    while i < len(pattern):
        if pattern[i] == pattern[j]:
            j += 1
            lps[i] = j
            i += 1
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                lps[i] = 0
                i += 1

    # Search the pattern in the text using the LPS array
    i = 0  # index for text
    j = 0  # index for pattern
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1

        if j == len(pattern):
            return i - j  # Pattern found, return the starting index

        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1  # Pattern not found

