def is_prime(n):
    """
    Checks if a given number or a list of numbers is prime.

    Parameters:
    n (int, list): A single integer or a list of integers to check for primality.

    Returns:
    bool, list: A boolean if a single integer is given, or a list of booleans if a
                list of integers is provided, corresponding to whether each number is prime.
    """
    def check_prime(number):
        if number <= 1:
            return False
        if number == 2:
            return True
        if number % 2 == 0:
            return False
        for i in range(3, int(number**0.5) + 1, 2):
            if number % i == 0:
                return False
        return True

    if isinstance(n, list):
        return [check_prime(num) for num in n]

    return check_prime(n)

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression given as a string.
    Returns the result if the expression is valid, otherwise returns an error message.
    """
    try:
        result = eval(expression)
        return result
    except (SyntaxError, NameError, TypeError) as e:
        return f"Error evaluating expression: {str(e)}"
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"

