def swap_dict_keys_values(d):
    """
    Swaps the keys and values of the given dictionary.
    If a value is not unique, it appends the keys to a list.

    Args:
    d (dict): The input dictionary.

    Returns:
    dict: A dictionary with keys and values swapped.
    """
    result = {}
    for key, value in d.items():
        if value in result:
            if isinstance(result[value], list):
                result[value].append(key)
            else:
                result[value] = [result[value], key]
        else:
            result[value] = key
    return result

