def is_prime(n):
    """
    Check whether a given integer n is a prime number.

    Parameters:
    n (int): The integer to check for primality

    Returns:
    bool: True if n is prime, False otherwise
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def caesar_cipher(message, shift, encrypt=True):
    """
    Encrypts or decrypts a message using a Caesar cipher.

    Parameters:
    - message: The message to be encrypted or decrypted.
    - shift: The shift value for the Caesar cipher.
    - encrypt: Boolean flag indicating whether to encrypt or decrypt.

    Returns:
    - The encrypted or decrypted message.
    """
    if not encrypt:
        shift = -shift

    result = []
    for char in message:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                start = ord('a')
                shifted_char = chr((ord(char) - start + shift_amount) % 26 + start)
            elif char.isupper():
                start = ord('A')
                shifted_char = chr((ord(char) - start + shift_amount) % 26 + start)
            result.append(shifted_char)
        else:
            result.append(char)

    return ''.join(result)

