def find_largest_element(lst):
    """
    Returns the largest element in a list of integers.
    If the list is empty, returns None.
    If the list contains non-integer elements, raises ValueError.
    """
    if not lst:
        return None

    for elem in lst:
        if not isinstance(elem, int):
            raise ValueError("List contains non-integer elements")

    return max(lst)

def mode(lst):
    """
    Find the mode (most frequent value) in a list of integers.
    If multiple values have the same highest frequency,
    return the one that appears first in the list.
    """
    if not lst:
        return None

    frequency = {}
    for item in lst:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1

    max_freq = max(frequency.values())
    for item in lst:
        if frequency[item] == max_freq:
            return item

def mode_using_min(lst):
    """
    Find the mode (most frequent value) in a list of integers using the min() function.
    If multiple values have the same highest frequency,
    return the one that appears first in the list.
    """
    if not lst:
        return None

    frequency = {}
    for item in lst:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1

    max_freq = min(frequency.values(), key=lambda x: -x)
    for item in lst:
        if frequency[item] == max_freq:
            return item

