def is_even(n):
    """
    Determines if the given number n is even.
    """
    if n == 0:
        return True
    return is_odd(n - 1)

def is_odd(n):
    """
    Determines if the given number n is odd.
    """
    if n == 0:
        return False
    return is_even(n - 1)

def tail_factorial(n, acc=1):
    """
    Returns the factorial of n using tail recursion.
    """
    if n == 0:
        return acc
    return tail_factorial(n - 1, acc * n)

