def sum_tuples(tuples_list):
    """
    Returns a tuple containing the sums of the elements at each index in the tuples.
    """
    # Initialize sums as a list of zeros with the same length as the tuple elements
    sums = [0] * len(tuples_list[0])

    for item in tuples_list:
        for index, value in enumerate(item):
            sums[index] += value

    return tuple(sums)

