def has_permission(user_roles, resource_permissions):
    """
    Check if any of the user's roles have the necessary permissions to perform actions on a resource.

    :param user_roles: A list of roles the user has, e.g., ["admin", "editor"]
    :param resource_permissions: A dictionary mapping roles to permissions, e.g.,
                                {
                                    "admin": ["read", "write", "delete"],
                                    "editor": ["read", "write"],
                                    "viewer": ["read"]
                                }
    :return: True if user has the necessary permissions, False otherwise
    """
    for role in user_roles:
        if role in resource_permissions:
            permissions = resource_permissions[role]
            if "all" in permissions or "read" in permissions or "write" in permissions:
                return True
    return False

