def generate_truth_table(operator_name):
    def AND(a, b): return a and b
    def OR(a, b): return a or b
    def NOT(a): return not a
    def NAND(a, b): return not (a and b)
    def NOR(a, b): return not (a or b)
    def XOR(a, b): return a != b
    def XNOR(a, b): return a == b

    operators = {
        'AND': AND,
        'OR': OR,
        'NOT': NOT,
        'NAND': NAND,
        'NOR': NOR,
        'XOR': XOR,
        'XNOR': XNOR,
    }

    if operator_name not in operators:
        raise ValueError(f"Unknown operator: {operator_name}")

    if operator_name == 'NOT':
        return [(a, operators[operator_name](a)) for a in (0, 1)]
    else:
        return [(a, b, operators[operator_name](a, b)) for a in (0, 1) for b in (0, 1)]

