def process_changes(changes):
    """
    Processes the changes based on their type (added, removed, modified) and performs specific validation.
    """
    def validate_added(item):
        # Example validation for added items: id and name must not be None
        if item["id"] is None or item["name"] is None:
            return False
        return True

    def validate_removed(item):
        # Example validation for removed items: id must be even
        if item["id"] % 2 != 0:
            return False
        return True

    def validate_modified(item):
        # Example validation for modified items: name must not be same as previous_name
        if item["name"] == item["previous_name"]:
            return False
        return True

    validated_changes = {
        "added": [],
        "removed": [],
        "modified": []
    }

    for added_item in changes.get("added", []):
        if validate_added(added_item):
            validated_changes["added"].append(added_item)

    for removed_item in changes.get("removed", []):
        if validate_removed(removed_item):
            validated_changes["removed"].append(removed_item)

    for modified_item in changes.get("modified", []):
        if validate_modified(modified_item):
            validated_changes["modified"].append(modified_item)

    return validated_changes

