def is_prime(n):
    """
    Checks if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_of_primes_in_range(start, end):
    """
    Calculate the sum of all prime numbers within a given range, including the endpoints.
    """
    total = 0
    for number in range(start, end + 1):
        if is_prime(number):
            total += number
    return total

