def factorial(n):
    """
    Returns the factorial of a given number n using recursion.
    """
    # base case: factorial of 0 or 1 is 1
    if n == 0 or n == 1:
        return 1

    # recursive case: n! = n * (n-1)!
    else:
        return n * factorial(n-1)

