def factorial(n):
    """
    Returns the factorial of a non-negative integer n.
    Handles large numbers efficiently using iterative approach.
    """
    if n < 0:
        raise ValueError("Negative integers do not have factorials.")
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

