def char_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the input string.
    Case insensitive and considers only alphabetic characters.
    """
    s = s.lower()
    frequency = {}
    for char in s:
        if char.isalpha():
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

