import heapq

def dijkstra(graph, start):
    """
    The function implements Dijkstra's shortest path algorithm.
    :param graph: Dictionary representing the adjacency list of the graph {node: [(neighbor, weight), ...]}
    :param start: The starting node for Dijkstra's algorithm
    :return: Dictionary of the shortest distances from the start to each node {node: distance}
    """
    # Initialize the priority queue
    priority_queue = [(0, start)]
    # Distance dictionary
    distances = {node: float('inf') for node in graph}
    # Distance to the source is zero
    distances[start] = 0

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # Skip the processing of the node if a shorter path to it has been found
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path to the neighbor has been found
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

