def convert_temperature(value, from_unit, to_unit):
    """
    Converts temperature between Celsius, Fahrenheit, and Kelvin.

    Parameters:
    value (float): The temperature value to convert.
    from_unit (str): The unit of the input temperature ('C', 'F', 'K').
    to_unit (str): The unit of the output temperature ('C', 'F', 'K').

    Returns:
    float: The converted temperature value.
    """
    from_unit = from_unit.upper()
    to_unit = to_unit.upper()

    if from_unit == to_unit:
        return value

    # Convert from the input unit to Celsius
    if from_unit == 'C':
        celsius = value
    elif from_unit == 'F':
        celsius = (value - 32) * 5 / 9
    elif from_unit == 'K':
        celsius = value - 273.15
    else:
        raise ValueError("Invalid from_unit. Only 'C', 'F', 'K' are allowed.")

    # Convert from Celsius to the output unit
    if to_unit == 'C':
        return celsius
    elif to_unit == 'F':
        return celsius * 9 / 5 + 32
    elif to_unit == 'K':
        return celsius + 273.15
    else:
        raise ValueError("Invalid to_unit. Only 'C', 'F', 'K' are allowed.")

