import json
import re

def json_tagged_decode(data):
    """
    Decode JSON data that includes tagged values.

    The function identifies tags in the format `@<tag>:<value>` and converts them into proper data structures.

    Args:
    - data (str): The JSON encoded string.

    Returns:
    - The decoded Python object.
    """

    def decode_tagged_dict(d):
        for k, v in d.items():
            if isinstance(v, str):
                if m := re.match(r"^@(\w+):(.*)$", v):
                    tag, value = m.groups()
                    if tag == "int":
                        d[k] = int(value)
                    elif tag == "float":
                        d[k] = float(value)
                    elif tag == "bool":
                        d[k] = value.lower() == "true"
                    # Add more conversions if needed
        return d

    decoded = json.loads(data, object_hook=decode_tagged_dict)
    return decoded

