def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If all characters are repeating, returns None.
    """
    char_count = {}

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that only appears once
    for char in s:
        if char_count[char] == 1:
            return char

    return None

