def is_subsequence(str1, str2):
    """
    Checks if str1 is a subsequence of str2 using recursion.
    """
    # Base cases
    if not str1:
        return True
    if not str2:
        return False

    # Recursive cases
    if str1[0] == str2[0]:
        return is_subsequence(str1[1:], str2[1:])
    else:
        return is_subsequence(str1, str2[1:])

