def tribonacci(n):
    """
    Returns the first n Tribonacci numbers.
    """
    if n == 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    trib = [0, 1, 1]

    for i in range(3, n):
        next_val = trib[-1] + trib[-2] + trib[-3]
        trib.append(next_val)

