def calculate_sum(n):
    """
    Calculate the sum of all integers from 1 to n using a for loop.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def calculate_sum_formula(n):
    """
    Calculate the sum of all integers from 1 to n using the formula.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    return n * (n + 1) // 2

def compare_results(n):
    """
    Compare the results obtained from both calculate_sum and calculate_sum_formula functions.
    """
    return calculate_sum(n) == calculate_sum_formula(n)

def sum_list(numbers):
    """
    Returns the sum of all the numbers in the list.
    If the input is not a list or contains non-numeric elements, raises a TypeError.
    """
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of numbers")

    for element in numbers:
        if not isinstance(element, (int, float)):
            raise TypeError("Input must be a list of numbers")

    return sum(numbers)

