def find_duplicates(lst):
    """
    Returns a new list containing only the duplicate elements
    from the input list, preserving order.
    """
    seen = set()
    duplicates = set()

    for item in lst:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)

    return [item for item in lst if item in duplicates]

