def longest_subarray(arr):
    if not arr:
        return 0

    element_freq = {}

    # Iterate to capture block frequencies and lengths
    for i in range(len(arr)):
        count = 1
        while i + 1 < len(arr) and arr[i] == arr[i + 1]:
            count += 1
            i += 1
        element = arr[i]
        if element not in element_freq:
            element_freq[element] = {'total_freq': 0, 'max_block_len': 0}
        element_freq[element]['total_freq'] += count
        element_freq[element]['max_block_len'] = max(element_freq[element]['max_block_len'], count)

    # Now find the maximum frequency element and its longest block length
    max_freq = 0
    max_len = 0
    for element in element_freq:
        if element_freq[element]['total_freq'] > max_freq:
            max_freq = element_freq[element]['total_freq']
            max_len = element_freq[element]['max_block_len']
        elif element_freq[element]['total_freq'] == max_freq:
            max_len = max(max_len, element_freq[element]['max_block_len'])

    return max_len

