def find_centroid_point(nums):
    """
    Returns the centroid point that minimizes the sum of the distances to all other points in the array.
    """
    nums.sort()
    n = len(nums)

    # The optimal position is the median.
    if n % 2 == 1:
        return nums[n // 2]
    else:
        return min(nums[n // 2 - 1], nums[n // 2])

