def max_length_more_evens(arr):
    """
    Returns the maximum length of a contiguous subarray that has more even numbers than odd numbers.
    If no such subarray exists, returns 0.
    """
    n = len(arr)
    even_count = 0
    odd_count = 0
    max_length = 0
    count_diff_map = {0: -1}

    for i in range(n):
        if arr[i] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

        diff = even_count - odd_count

        if diff > 0:
            max_length = i + 1
        elif diff in count_diff_map:
            max_length = max(max_length, i - count_diff_map[diff])
        else:
            count_diff_map[diff] = i

    return max_length

