def is_feasible(pages, n, k, max_pages):
    students_required = 1
    current_pages = 0

    for i in range(n):
        if current_pages + pages[i] > max_pages:
            students_required += 1
            current_pages = pages[i]
            if students_required > k:
                return False
        else:
            current_pages += pages[i]

    return True

def min_max_pages(pages, n, k):
    if n < k:
        return -1

    start = max(pages)
    end = sum(pages)
    result = end

    while start <= end:
        mid = (start + end) // 2
        if is_feasible(pages, n, k, mid):
            result = mid
            end = mid - 1
        else:
            start = mid + 1

    return result

