def demolish_buildings(height, k):
    """
    Returns the number of buildings before and after demolitions to form a strictly increasing sequence.
    If not possible, returns [-1, -1].

    Args:
    height (list of int): List of heights of buildings.
    k (int): Number of buildings to be demolished.

    Returns:
    list of int: The number of buildings before and after demolitions, or [-1, -1] if not possible.
    """
    n = len(height)
    if k >= n:
        return [-1, -1]

    dp = [1] * n
    for i in range(1, n):
        for j in range(0, i):
            if height[j] < height[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_increasing_subsequence_length = max(dp)

    if max_increasing_subsequence_length + k >= n:
        return [n, max_increasing_subsequence_length]
    else:
        return [-1, -1]

