def minimize_sum_of_max_values(arr, k):
    n = len(arr)

    # Function to check if a maximum sum can be achieved with division into k parts
    def can_split_with_max_sum(max_sum):
        current_sum = 0
        parts = 1
        for num in arr:
            if current_sum + num > max_sum:
                parts += 1
                current_sum = num
                if parts > k:
                    return False
            else:
                current_sum += num
        return True

    # Binary search over the range of possible maximum subarray sums
    left, right = max(arr), sum(arr)
    while left < right:
        mid = (left + right) // 2
        if can_split_with_max_sum(mid):
            right = mid
        else:
            left = mid + 1

    return left

