def min_largest_split(s, k):
    """
    Returns the length of the smallest possible largest substring
    among the k substrings formed by splitting s into k parts.
    """
    def can_divide(max_length):
        chunks = 1
        current_length = 0
        for char in s:
            current_length += 1
            if current_length > max_length:
                chunks += 1
                current_length = 1
                if chunks > k:
                    return False
        return True

    left, right = max(len(s) // k, 1), len(s)
    while left < right:
        mid = (left + right) // 2
        if can_divide(mid):
            right = mid
        else:
            left = mid + 1
    return left

