def is_monotonic(nums):
    """
    Determines if the array of integers 'nums' is monotonic.
    An array is considered monotonic if it is either entirely non-increasing or non-decreasing.

    :param nums: List[int] - the list of integers to check
    :return: bool - True if the array is monotonic, False otherwise
    """

    if not nums:
        return True

    increasing = decreasing = True

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            decreasing = False
        if nums[i] < nums[i-1]:
            increasing = False

    return increasing or decreasing

