def can_convert(s, t):
    """
    Determines if string `s` can be converted to string `t` using the given operations.

    Parameters:
    s (str): The source string.
    t (str): The target string.

    Returns:
    bool: True if `s` can be converted to `t`, False otherwise.
    """
    if len(s) != len(t):
        return False

    if s == t:
        return True

    # Track character mappings from s to t
    s_to_t = {}
    t_mapped = set()

    for char_s, char_t in zip(s, t):
        if char_s in s_to_t:
            if s_to_t[char_s] != char_t:
                return False
        else:
            if char_t in t_mapped:
                return False
            s_to_t[char_s] = char_t
            t_mapped.add(char_t)

    return True

