def is_hexadecimal(s):
    """
    Determines if a given string is a valid hexadecimal number.

    Parameters:
    s (str): The string to check.

    Returns:
    bool: True if the string is a valid hexadecimal number, False otherwise.
    """
    if len(s) == 0:
        return False

    # Check for optional “0x” or “0X” prefix
    if s[:2].lower() == "0x":
        s = s[2:]

    if len(s) == 0:
        return False

    # Check if the remaining characters are valid hexadecimal characters
    for char in s:
        if not (char.isdigit() or 'a' <= char.lower() <= 'f'):
            return False

    return True

