from typing import List

def min_days_to_complete_projects(projects: List[int], workers: int) -> int:
    def feasible(days: int) -> bool:
        required_workers = 1
        current_time = 0

        for project in projects:
            if current_time + project <= days:
                current_time += project
            else:
                required_workers += 1
                current_time = project
                if required_workers > workers:
                    return False
        return True

    low, high = max(projects), sum(projects)
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    return low

