def simulate_stack(n, commands):
    stack = []
    result = []

    for command in commands:
        if "PUSH" in command:
            _, value = command.split()
            stack.append(int(value))
        elif command == "POP":
            if stack:
                result.append(stack.pop())
            else:
                result.append(-1)

    return result

import heapq
from collections import defaultdict, deque

def find_cheapest_price(n, flights, source, destination, k):
    # Create an adjacency list for the graph representation
    graph = defaultdict(list)
    for u, v, w in flights:
        graph[u].append((v, w))

    # Priority queue to hold (cost, current city, stops)
    pq = [(0, source, 0)]

    # Dictionary to record the minimum cost to reach each node with at most a certain number of stops
    costs = {(source, 0): 0}

    while pq:
        cost, node, stops = heapq.heappop(pq)

        # If we reach the destination within the allowed stops, return the cost
        if node == destination and stops <= k + 1:
            return cost

        # If we can still make a stop
        if stops <= k:
            for nei, price in graph[node]:
                next_cost = cost + price
                if (nei, stops + 1) not in costs or next_cost < costs[(nei, stops + 1)]:
                    costs[(nei, stops + 1)] = next_cost
                    heapq.heappush(pq, (next_cost, nei, stops + 1))

    return -1

def min_operations(source, target):
    """
    Return the minimum number of operations needed to transform 'source' to 'target'
    by either doubling the value of 'source' or subtracting one from 'source'.
    """
    if source > target:
        return source - target

    operations = 0
    while target > source:
        if target % 2 == 0:
            target //= 2
        else:
            target += 1
        operations += 1

    return operations + (source - target)

