def split_string(s):
    """
    Split the string into the minimum number of substrings such that each letter appears in only one substring.
    """
    last_occurrence = {ch: idx for idx, ch in enumerate(s)}
    start = 0
    end = 0
    result = []

    for idx, ch in enumerate(s):
        end = max(end, last_occurrence[ch])
        if idx == end:
            result.append(s[start:end + 1])
            start = end + 1

    return result

