def longestValidParentheses(s):
    """
    Returns the length of the longest valid (well-formed) parentheses substring.

    Args:
    s (str): Input string containing only '(' and ')'

    Returns:
    int: Length of the longest valid parentheses substring
    """
    max_len = 0
    stack = [-1]

    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            stack.pop()
            if len(stack) == 0:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])

    return max_len

