def find_max_length_of_common_subarray(nums1, nums2):
    """
    Finds the maximum length of any common subarray between nums1 and nums2.
    """
    n = len(nums1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    max_length = 0

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_length = max(max_length, dp[i][j])

    return max_length

def max_non_overlapping_keys(s, t):
    max_keys = 0
    substr_lens = len(t[0])
    seen_indices = set()

    for key in t:
        start = 0
        while start <= len(s) - substr_lens:
            idx = s.find(key, start)
            if idx == -1:
                break
            if all(i not in seen_indices for i in range(idx, idx + substr_lens)):
                max_keys += 1
                seen_indices.update(range(idx, idx + substr_lens))
                start = idx + substr_lens
            else:
                start = idx + 1

    return max_keys

