from typing import List
import heapq

def trap_rain_water(elevation_map: List[List[int]]) -> int:
    if not elevation_map or not elevation_map[0]:
        return 0

    m, n = len(elevation_map), len(elevation_map[0])
    visited = [[False] * n for _ in range(m)]
    min_heap = []

    def _neighbors(x: int, y: int) -> list:
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                yield nx, ny

    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(min_heap, (elevation_map[i][j], i, j))
                visited[i][j] = True

    trapped_water = 0
    while min_heap:
        height, x, y = heapq.heappop(min_heap)
        for nx, ny in _neighbors(x, y):
            if not visited[nx][ny]:
                trapped_water += max(0, height - elevation_map[nx][ny])
                heapq.heappush(min_heap, (max(height, elevation_map[nx][ny]), nx, ny))
                visited[nx][ny] = True

    return trapped_water

def unique_subsequences(s):
    def generate_subsequences(s):
        if not s:
            return {''}
        # Exclude the first character and generate subsequences of the remaining string
        subsequences = generate_subsequences(s[1:])
        # Include the first character to the subsequences
        new_subsequences = {s[0] + subseq for subseq in subsequences}
        return subsequences | new_subsequences

    # Generate all subsequences
    all_subsequences = generate_subsequences(s)
    # Remove the empty string and sort the rest
    result = sorted(subseq for subseq in all_subsequences if subseq)
    return result

