def max_profit(prices):
    if not prices or len(prices) < 2:
        return (0, 0, 0)

    min_price = prices[0]
    min_day = 0
    max_profit = 0
    buy_day = 0
    sell_day = 0

    for current_day in range(1, len(prices)):
        current_price = prices[current_day]

        # Check if the current day price - min price is the highest profit so far
        if current_price - min_price > max_profit:
            max_profit = current_price - min_price
            buy_day = min_day
            sell_day = current_day

        # Update the minimum price and corresponding day
        if current_price < min_price:
            min_price = current_price
            min_day = current_day

    return (buy_day, sell_day, max_profit)

