from datetime import datetime, timedelta

def longestPurchaseStreak(purchases):
    if not purchases:
        return 0

    # Sort and convert the dates from strings to datetime objects
    purchase_dates = sorted(datetime.strptime(date, "%Y-%m-%d") for date in purchases)

    max_streak = 1
    current_streak = 1

    for i in range(1, len(purchase_dates)):
        if purchase_dates[i] == purchase_dates[i - 1] + timedelta(days=1):
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 1

    return max_streak

