def are_brackets_balanced(s):
    """
    Checks if the brackets in the given string are balanced.

    Args:
    s (str): The input string containing brackets.

    Returns:
    bool: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            # In case of any other character (which shouldn't be there by the problem statement)
            return False

    return stack == []

