def sum_nested_values(input_list):
    """
    Returns the sum of all numerical values in the list, including nested structures.
    Ignores non-numerical values.
    """
    def helper(data):
        total = 0
        if isinstance(data, (int, float)):
            return data
        if isinstance(data, list):
            for item in data:
                total += helper(item)
        elif isinstance(data, dict):
            for key, value in data.items():
                total += helper(value)
        return total

    return helper(input_list)

