def max_consecutive_occurrences(s):
    """
    Returns the maximum number of consecutive occurrences of the same character in a given string.
    """
    if not s:
        return 0

    max_count = 1
    current_count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 1

    return max(max_count, current_count)

