import math

def lcm(a, b):
    """
    Returns the least common multiple of a and b.
    """
    return abs(a*b) // math.gcd(a, b)

def smallest_multiple(n):
    """
    Returns the smallest positive number that is evenly divisible by all numbers from 1 to n.
    """
    result = 1
    for i in range(1, n+1):
        result = lcm(result, i)
    return result

# The function to get the smallest number that is evenly divisible by all numbers from 1 to 20
def smallest_multiple_1_to_20():
    return smallest_multiple(20)

