def power(n, m):
    """
    Calculates n raised to the power of m using recursion.

    Parameters:
    n (int or float): The base number
    m (int): The exponent

    Returns:
    int or float: The result of n raised to the power of m
    """
    if m == 0:
        return 1
    elif m > 0:
        return n * power(n, m - 1)
    else:
        return 1 / power(n, -m)

