def caesar_cipher(text, key):
    """
    Encrypts the input text using the Caesar cipher algorithm.

    Args:
    text (str): the plaintext string to encrypt.
    key (int): the number of positions to shift each character.

    Returns:
    str: the encrypted string.
    """
    encrypted = []
    for char in text:
        if char.isalpha():
            shift = key % 26
            if char.islower():
                encrypted.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
            else:
                encrypted.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        else:
            encrypted.append(char)
    return ''.join(encrypted)

