def third_max(nums):
    """
    Returns the third maximum number in an array. If the third maximum does not exist,
    return the maximum number. If there are only two unique numbers, return the highest number.
    """
    nums = set(nums)  # Remove duplicates
    if len(nums) < 3:
        return max(nums)
    nums.remove(max(nums))
    nums.remove(max(nums))
    return max(nums)

