def find_min_max(arr):
    """
    Returns a tuple (min_value, max_value) representing the minimum and maximum
    values in the given array of integers.

    :param arr: List of integers
    :return: Tuple of integers (min_value, max_value)
    """
    if not arr:
        raise ValueError("Array must not be empty")

    min_value = max_value = arr[0]

    for num in arr[1:]:
        if num < min_value:
            min_value = num
        if num > max_value:
            max_value = num

    return (min_value, max_value)

