def custom_sum(a, b):
    """
    Returns the sum of a and b. If the sum is even, multiplies it by 3.
    If the sum is odd, multiplies it by 2.
    """
    sum_result = a + b
    if sum_result % 2 == 0:
        return sum_result * 3
    else:
        return sum_result * 2

