    # Helper function to handle numbers less than 1000
    def helper(n):
        if n < 20:
            return below_20[n]
        elif n < 100:
            return tens[n // 10] + ('' if n % 10 == 0 else '-' + below_20[n % 10])
        else:
            return below_20[n // 100] + ' hundred' + ('' if n % 100 == 0 else ' ' + helper(n % 100))

    if num == 0:
        return 'zero'

    below_20 = [
        '', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
        'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
        'seventeen', 'eighteen', 'nineteen'
    ]

    tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

    thousands = ['', ' thousand', ' million', ' billion']

    words = ''
    for i, chunk in enumerate(chunk_number(num)):
        if chunk:
            words = helper(chunk) + thousands[i] + ('' if words == '' else ' ' + words)

    return words.strip()

def chunk_number(num):
    while num > 0:
        yield num % 1000
        num //= 1000

def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in a sequence of numbers.
    """
    if not nums:
        return 0

    # DP array to store the length of LIS ending at each index
    lis = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

