def remove_duplicates(s):
    """
    Removes duplicate characters from the given string while preserving the order of characters.

    :param s: The input string.
    :return: A new string with duplicate characters removed.
    """
    seen = set()
    output = []
    for char in s:
        if char not in seen:
            seen.add(char)
            output.append(char)
    return "".join(output)

