def count_letter_frequency(s):
    """
    Returns a dictionary with the frequency of each letter in the given string s.
    """
    frequency = {}
    for letter in s:
        if letter.isalpha():  # Only counting letters, ignoring other characters
            letter = letter.lower()  # Convert to lower case to ensure case insensitivity
            if letter in frequency:
                frequency[letter] += 1
            else:
                frequency[letter] = 1
    return frequency

