def is_valid(grid, row, col, num):
    N = len(grid)
    for x in range(N):
        if grid[row][x] == num:
            return False
        if grid[x][col] == num:
            return False
    return True

def solve_grid(grid, N):
    for row in range(N):
        for col in range(N):
            if grid[row][col] == 0:
                for num in range(1, N + 1):
                    if is_valid(grid, row, col, num):
                        grid[row][col] = num
                        if solve_grid(grid, N):
                            return True
                        grid[row][col] = 0
                return False
    return True

def solve_puzzle(grid):
    N = len(grid)
    solve_grid(grid, N)
    return grid

