def count_palindromic_substrings(s):
    """
    Returns the count of palindromic substrings in the given string s.
    """
    def is_palindrome(substring):
        return substring == substring[::-1]

    count = 0
    n = len(s)

    for i in range(n):
        for j in range(i, n):
            if is_palindrome(s[i:j+1]):
                count += 1

    return count

