def is_valid_integer(s):
    """
    Checks if the given string is a valid integer.

    Parameters:
    s (str): The string to validate.

    Returns:
    bool: True if the string is a valid integer, False otherwise.
    """
    if not s:
        return False

    if s[0] in ('-', '+'):
        if len(s) == 1:
            return False
        return s[1:].isdigit()

    return s.isdigit()

