def longest_even_product_subarray(test_cases):
    results = []
    for n, arr in test_cases:
        max_length = 0
        current_length = 0
        for num in arr:
            if num % 2 == 0:
                max_length = max(max_length, current_length + 1)
                current_length = len(arr)
                break
            else:
                current_length += 1
        results.append(n if max_length else 0)
    return results

