def parse_and_solve(input_str):
    input_lines = input_str.strip().split('\n')
    T = int(input_lines[0])
    index = 1
    test_cases = []
    for _ in range(T):
        n = int(input_lines[index])
        arr = list(map(int, input_lines[index + 1].split()))
        test_cases.append((n, arr))
        index += 2
    return longest_even_product_subarray(test_cases)

def count_peaks(grid, N, M):
    """
    Returns the number of distinct peaks in the given grid.

    :param grid: List of lists, where each sublist is a row of the grid.
    :param N: Number of rows.
    :param M: Number of columns.
    :return: Number of distinct peaks.
    """
    def is_peak(i, j):
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                ni, nj = i + di, j + dj
                if (di != 0 or dj != 0) and 0 <= ni < N and 0 <= nj < M:
                    if grid[i][j] <= grid[ni][nj]:
                        return False
        return True

    peak_count = 0

    for i in range(N):
        for j in range(M):
            if grid[i][j] > 0 and is_peak(i, j):
                peak_count += 1

    return peak_count

