def num_paths(N, M, grid):
    MOD = 1000000007

    if grid[0][0] == '#' or grid[N-1][M-1] == '#':
        return 0

    dp = [[0 for _ in range(M)] for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[N-1][M-1]

