def largest_square(grid, M, N):
    if not grid:
        return 0

    # Initialize variables
    max_side = 0
    dp = [[0] * N for _ in range(M)]

    # Iterate over the grid to fill dp
    for i in range(M):
        for j in range(N):
            if grid[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

def process_input(input_data):
    lines = input_data.strip().split("\n")
    T = int(lines[0])
    results = []
    idx = 1
    for _ in range(T):
        M, N = map(int, lines[idx].split())
        grid = [lines[idx + 1 + i] for i in range(M)]
        results.append(largest_square(grid, M, N))
        idx += M + 1
    return results

