def remove_duplicates(text):
    """
    Removes duplicate characters from the string while preserving the order of
    their first occurrence.
    """
    if text is None:
        return None

    seen = set()
    result = []
    for char in text:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

