from math import isclose

def check_collinear(p1, p2, p3):
    """
    Check if three points are collinear.
    """
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    return (y2 - y1) * (x3 - x2) == (y3 - y2) * (x2 - x1)

def find_circle(points):
    n = len(points)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if not check_collinear(points[i], points[j], points[k]):
                    return "yes"
    return "no"

def circle_from_points(n, coordinates):
    points = [tuple(map(int, coordinates[i].split())) for i in range(n)]
    return find_circle(points)

