from collections import defaultdict
from datetime import datetime

def date_with_most_employees(dates):
    date_counts = defaultdict(int)

    # Count each occurrence of date
    for date in dates:
        date_counts[date] += 1

    # Find date with most employees
    max_count = 0
    max_date = None
    for date, count in date_counts.items():
        if count > max_count:
            max_count = count
            max_date = date
        elif count == max_count:
            # Check if current date is earlier than max_date
            if datetime.strptime(date, '%Y-%m-%d') < datetime.strptime(max_date, '%Y-%m-%d'):
                max_date = date

    return max_date

