def process_queries(queries):
    """
    This function processes a list of queries to manage a pool of integers and return results of specific queries.
    """
    pool = []
    results = []

    for query in queries:
        q_type, value = query
        if q_type == 1:
            pool.append(value)
        elif q_type == 2:
            if value in pool:
                pool.remove(value)
        elif q_type == 3:
            if pool:
                results.append(max(pool))
            else:
                results.append("None")

    return results

