def longest_subsequence_length(N, S, sequence):
    """
    Finds the length of the longest contiguous subsequence that sums to S.
    Returns 0 if no such subsequence exists.
    """
    sum_dict = {}
    current_sum = 0
    max_length = 0

    for i in range(N):
        current_sum += sequence[i]

        if current_sum == S:
            max_length = i + 1

        if (current_sum - S) in sum_dict:
            max_length = max(max_length, i - sum_dict[current_sum - S])

        if current_sum not in sum_dict:
            sum_dict[current_sum] = i

    return max_length

def is_path_possible(m, n, grid):
    """
    Returns "YES" if there is a path from the top-left to bottom-right corner avoiding obstacles,
    otherwise returns "NO".
    """
    def dfs(x, y):
        if x < 0 or y < 0 or x >= m or y >= n or grid[x][y] == 1 or visited[x][y]:
            return False
        if x == m - 1 and y == n - 1:
            return True
        visited[x][y] = True
        if dfs(x + 1, y) or dfs(x, y + 1) or dfs(x - 1, y) or dfs(x, y - 1):
            return True
        return False

    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return "NO"

    visited = [[False for _ in range(n)] for _ in range(m)]
    return "YES" if dfs(0, 0) else "NO"

