def unique_paths_with_k_steps(n, m, k, grid):
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    dp = [[[0 for _ in range(k+1)] for _ in range(m)] for _ in range(n)]
    dp[0][0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                continue
            for s in range(k+1):
                if i > 0:
                    dp[i][j][s] += dp[i-1][j][s-1] if s > 0 else 0
                if j > 0:
                    dp[i][j][s] += dp[i][j-1][s-1] if s > 0 else 0

    total_paths = 0
    for s in range(k+1):
        total_paths += dp[n-1][m-1][s]

    return total_paths

