from collections import deque

def is_safe_path(grid):
    n = len(grid)
    if grid[0][0] == 0 or grid[-1][-1] == 0:
        return "NO"

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0)])
    visited = set((0, 0))

    while queue:
        x, y = queue.popleft()

        if (x, y) == (n-1, n-1):
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == 1:
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "NO"

