def perform_operations(n, m, operations):
    sequence = [0] * n

    for op in operations:
        if op[0] == 1:
            i = op[1] - 1
            v = op[2]
            sequence[i] += v
        elif op[0] == 2:
            l = op[1] - 1
            r = op[2] - 1
            for j in range(l, r + 1):
                sequence[j] += 1

    return sequence

