import math
from functools import reduce

def find_gcd(x, y):
    """
    Returns the greatest common divisor (GCD) of x and y using the Euclidean algorithm.
    """
    while y:
        x, y = y, x % y
    return x

def largest_divisor(arr):
    """
    Finds the largest integer k such that all elements in the array can be divided by k without a remainder.
    """
    return reduce(find_gcd, arr)

def find_largest_divisor(n, arr):
    """
    Wrapper function to find the largest divisor given n and array of integers arr.
    """
    if n == 1:
        return arr[0]
    return largest_divisor(arr)

