from collections import deque

def process_operations(T, operations):
    results = []
    for i in range(T):
        queue = deque()
        current_ops = operations[i]
        for op in current_ops:
            if op.startswith("ENQUEUE"):
                _, val = op.split()
                queue.append(int(val))
            elif op == "DEQUEUE":
                if queue:
                    queue.popleft()
                else:
                    results.append("EMPTY QUEUE")
                    continue

            # If under DEQUEUE in non-empty/successful ENQUEUE case, append the current queue state
            if queue:
                results.append(" ".join(map(str, queue)))
            else:
                results.append("EMPTY QUEUE")

    return results

