def bloomingPeriods(h):
    n = len(h)
    if n == 0:
        return 0

    blooming_count = 0
    i = 0

    while i < n:
        start = i
        while i < n - 1 and h[i + 1] == h[i] + 1:
            i += 1

        if start != i:
            blooming_count += 1

        i += 1

    return blooming_count

