from typing import List, Tuple

def find_pairs(n: int, elements: List[int], target: int) -> List[Tuple[int, int]]:
    pairs = []
    elements.sort()
    used = set()
    for i in range(n):
        if elements[i] in used:
            continue
        for j in range(i + 1, n):
            if elements[j] in used:
                continue
            if elements[i] + elements[j] == target:
                pairs.append((elements[i], elements[j]))
                used.add(elements[i])
                used.add(elements[j])
                break
    return pairs

