def longest_substring_with_two_distinct_chars(s):
    if len(s) < 3:
        return s

    left = 0
    right = 0
    max_len = 2
    max_substr = s[:2]
    char_map = {}

    while right < len(s):
        char_map[s[right]] = right
        right += 1

        if len(char_map) > 2:
            del_idx = min(char_map.values())
            del char_map[s[del_idx]]
            left = del_idx + 1

        if right - left > max_len:
            max_len = right - left
            max_substr = s[left:right]

    return max_substr

