def captureRegions(matrix):
    if not matrix or not matrix[0]:
        return

    N, M = len(matrix), len(matrix[0])

    def dfs(i, j):
        if i < 0 or i >= N or j < 0 or j >= M or matrix[i][j] != 'O':
            return
        matrix[i][j] = 'E'  # Mark as escaped
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    # Mark the escaped 'O's on the boundary
    for i in range(N):
        for j in [0, M - 1]:
            if matrix[i][j] == 'O':
                dfs(i, j)

    for i in [0, N - 1]:
        for j in range(M):
            if matrix[i][j] == 'O':
                dfs(i, j)

    # Flip 'O' to 'X', and 'E' back to 'O'
    for i in range(N):
        for j in range(M):
            if matrix[i][j] == 'O':
                matrix[i][j] = 'X'
            elif matrix[i][j] == 'E':
                matrix[i][j] = 'O'

def isValidParentheses(S):
    """
    Returns 'Yes' if the string has valid parentheses, otherwise returns 'No'.
    """
    balance = 0
    for char in S:
        if char == '(':
            balance += 1
        elif char == ')':
            if balance == 0:
                return "No"
            balance -= 1
    return "Yes" if balance == 0 else "No"

def can_sort_by_reversing_subarray(arr):
    n = len(arr)

    # Find the start of the subarray to reverse
    i = 0
    while i < n - 1 and arr[i] <= arr[i + 1]:
        i += 1

    if i == n - 1:  # If already sorted
        return True

    # Find the end of the subarray to reverse
    j = n - 1
    while j > 0 and arr[j] >= arr[j - 1]:
        j -= 1

    # Reverse the subarray arr[i:j+1] and check if the array is sorted
    arr[i:j+1] = reversed(arr[i:j+1])
    return arr == sorted(arr)

def solve(test_cases):
    results = []
    for case in test_cases:
        if can_sort_by_reversing_subarray(case):
            results.append("YES")
        else:
            results.append("NO")
    return results

