def subset_sum(arr, target):
    n = len(arr)
    dp = [[False for _ in range(target + 1)] for _ in range(n + 1)]

    # There is always a subset with sum 0, the empty subset.
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

from typing import List

def canThreePartsEqualSum(arr: List[int]) -> bool:
    total_sum = sum(arr)

    if total_sum % 3 != 0:
        return False

    target_sum = total_sum // 3
    current_sum, parts_found = 0, 0

    for num in arr:
        current_sum += num
        if current_sum == target_sum:
            parts_found += 1
            current_sum = 0
        if parts_found == 2:
            return True

    return False

