def longest_increasing_sequence(n, events):
    sensor_data = {}
    longest_sequence = 0

    for t, s, v in events:
        if s not in sensor_data:
            sensor_data[s] = (v, 1)  # (prev_value, current_sequence_length)
        else:
            prev_value, current_length = sensor_data[s]
            if v > prev_value:
                current_length += 1
            else:
                current_length = 1

            sensor_data[s] = (v, current_length)

        longest_sequence = max(longest_sequence, sensor_data[s][1])

    return longest_sequence

def collect_flowers(n, flowers, m, paths, s):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in paths:
        graph[u].append(v)

    visited = [False] * (n + 1)
    total_flowers = 0
    queue = deque([s])

    while queue:
        current = queue.popleft()
        if not visited[current]:
            visited[current] = True
            total_flowers += flowers[current - 1]
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    queue.append(neighbor)

    return total_flowers

