def get_non_overlapping_gatherings(gatherings):
    def overlap(g1, g2):
        return not set(g1[1:]).isdisjoint(set(g2[1:]))

    sorted_gatherings = sorted(gatherings, key=lambda x: x[0])
    non_overlapping_set = []
    attendee_set = set()

    for gathering in sorted_gatherings:
        name, *attendees = gathering
        if not attendee_set.intersection(set(attendees)):
            non_overlapping_set.append(name)
            attendee_set.update(attendees)

    return sorted(non_overlapping_set)

