def hollow_square(n):
    """
    Returns a string representation of a hollow square with a '+' border
    and space inside for given integer n.
    """
    if n < 2:
        raise ValueError("n should be at least 2")

    top_bottom_row = '+' * n
    middle_row = '+' + ' ' * (n - 2) + '+' if n > 2 else '+' * n

    hollow_square = [top_bottom_row]

    for _ in range(n - 2):
        hollow_square.append(middle_row)

    if n > 1:
        hollow_square.append(top_bottom_row)

    return '\n'.join(hollow_square)

