def min_commands_to_remove(n, commands):
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    if (x + y) % 2 != 0:
        return -1

    return abs(x) + abs(y)

