def manage_garden(events):
    garden = []
    results = []

    for event in events:
        if event[0] == 0:
            # Plant a new plant with initial growth value x
            garden.append(event[1])
        elif event[0] == 1:
            # Water the plant at index i by increasing its growth value by x
            garden[event[1] - 1] += event[2]
        elif event[0] == 2:
            # Prune the plant at index i by decreasing its growth value by x
            garden[event[1] - 1] -= event[2]
        elif event[0] == 3:
            # Query the current growth value of the plant at index i
            results.append(garden[event[1] - 1])

    results.append("end")
    return results

def get_denominations(denominations):
    """
    Convert the binary representation of denominations into a list of coin values.
    """
    coin_values = [1, 5, 10, 25]
    available_coins = []

    for i in range(4):
        if (denominations >> i) & 1:
            available_coins.append(coin_values[i])

    return available_coins

def min_coins(amount, denominations):
    """
    Calculate the minimum number of coins needed to make the amount using the given denominations.
    """
    coins = get_denominations(denominations)
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if i >= coin:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

