def find_path_in_grid(n, m, grid):
    target = "snake"
    target_len = len(target)

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m

    def dfs(x, y, index, visited):
        if index == target_len:
            return True
        if not is_valid(x, y) or grid[x][y] != target[index]:
            return False

        visited.add((x, y))
        neighbors = [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]

        for nx, ny in neighbors:
            if (nx, ny) not in visited:
                if dfs(nx, ny, index+1, visited):
                    return True

        visited.remove((x, y))
        return False

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 's':
                if dfs(i, j, 0, set()):
                    return "YES"

    return "NO"

