def final_heights(N, Q, heights, spells):
    delta = [0] * (N + 1)  # using (N + 1) to handle range update easily

    # Apply all spells using a difference array approach
    for T, L, R in spells:
        delta[L-1] += T
        if R < N:
            delta[R] -= T

    # Calculate the final heights using the accumulated delta effect
    curr_delta = 0
    for i in range(N):
        curr_delta += delta[i]
        heights[i] += curr_delta

    return heights

