def first_non_repeating_char(s):
    """
    Returns the first non-repeating character in the string after filtering out special characters.
    If there is no such character, return "None".
    """
    # Step 1: Filter out special characters
    filtered_s = ''.join(c for c in s if c.isalpha())

    # Step 2: Create a dictionary to count character occurrences
    char_count = {}
    for char in filtered_s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Step 3: Find the first non-repeating character
    for char in filtered_s:
        if char_count[char] == 1:
            return char

    # If there is no non-repeating character, return "None"
    return "None"

