def dfs(grid, i, j, n, m, visited):
    if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] == 0 or visited[i][j]:
        return 0

    visited[i][j] = True
    count = 1
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for direction in directions:
        count += dfs(grid, i + direction[0], j + direction[1], n, m, visited)

    return count

def max_coins_collected(t, test_cases):
    results = []

    for test_case in test_cases:
        n, m, grid = test_case
        max_coins = 0
        visited = [[False] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1 and not visited[i][j]:
                    max_coins = max(max_coins, dfs(grid, i, j, n, m, visited))

        results.append(max_coins)

    return results

