def can_form_bst(nodes):
    """
    Returns "YES" if the given list of integers can form a valid BST.
    Otherwise, returns "NO".
    """
    def is_valid_bst(seq):
        if not seq:
            return True

        root = seq[0]
        left = [x for x in seq if x < root]
        right = [x for x in seq if x > root]

        # Check the continuity of left and right parts in the original sequence
        left_part = seq[1:len(left)+1]
        right_part = seq[len(left)+1:]

        if not (left == left_part and right == right_part):
            return False

        return is_valid_bst(left_part) and is_valid_bst(right_part)

    if is_valid_bst(nodes):
        return "YES"
    else:
        return "NO"

def check_bsts(cases):
    results = []
    for case in cases:
        n, nodes = case[0], case[1]
        results.append(can_form_bst(nodes))
    return results

