def can_modify_array(t, test_cases):
    results = []
    for i in range(t):
        n, k = test_cases[i][0]
        arr = test_cases[i][1]

        original_arr = arr[:]
        arr.sort()

        min_change_needed = sum(1 for i in range(n) if arr[i] != original_arr[i])

        if min_change_needed <= k:
            results.append(("YES", arr))
        else:
            results.append(("NO", []))

    return results

