def categorize_books(n, books):
    from collections import defaultdict
    categorized_books = defaultdict(list)

    # Parse the input and categorize books
    for book in books:
        title, genre = book.split(':')
        categorized_books[genre].append(title)

    # Sort genres and book titles
    sorted_genres = sorted(categorized_books.keys())
    result = []

    for genre in sorted_genres:
        result.append(f"{genre}:")
        for title in sorted(categorized_books[genre]):
            result.append(f"  {title}")

    return "\n".join(result)

from collections import defaultdict, deque

def process_trading_pairs(n, m, pairs):
    # Build graph adjacency list and in-degree array
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for a, b in pairs:
        graph[a].append(b)
        in_degree[b] += 1

    # Perform topological sort using Kahn's algorithm
    queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    topological_order = []

    while queue:
        node = queue.popleft()
        topological_order.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) == n:
        return "ORDERED", topological_order
    else:
        return "CYCLIC", []

